reg [ADDR_WIDTH-1:0] rd_addr;
reg [ADDR_WIDTH-1:0] wr_addr;
reg [BITSIZE_data_in-1:0] ram [DEPTH-1:0];
reg [ADDR_WIDTH:0] status_cnt;

// initialization of the fifio all data = 0
integer i;
initial begin
 for (i=0; i<DEPTH; i=i+1) begin
 ram[i] = {BITSIZE_data_in{1'b0}};
 end
end

assign full = (status_cnt > DEPTH-1);
assign empty = (status_cnt == 0);
assign data_out = ram[rd_addr];

always @(posedge clock) begin
 if (!reset) begin
 status_cnt <= 0;
 rd_addr <= 0;
 wr_addr <= 0;
 end else begin
 if (rd_en && !wr_en) begin
 rd_addr <= rd_addr +1;
 if (status_cnt != 0) begin
 status_cnt <= status_cnt -1;
 end
 end else if (wr_en && !rd_en) begin
 ram[wr_addr] <= data_in;
 wr_addr <= wr_addr +1;
 if (status_cnt != DEPTH) begin
 status_cnt <= status_cnt +1;
 end
 end else if (wr_en && rd_en) begin
 rd_addr <= rd_addr +1;
 wr_addr <= wr_addr +1;
 ram[wr_addr] <= data_in;
 end
 end
end

reg [ADDR_WIDTH-1:0] rd_addr;
reg [ADDR_WIDTH-1:0] wr_addr;
reg [BITSIZE_data_in-1:0] ram [DEPTH-1:0];
reg [ADDR_WIDTH:0] status_cnt;

integer i;
initial begin
 for (i=1; i<DEPTH; i=i+1) begin
 ram[i] = i;
 end
end

assign full = (status_cnt > DEPTH-1);
assign empty = (status_cnt == 0);

assign data_out = ram[rd_addr];

always @(posedge clock) begin
 if (!reset) begin
 status_cnt <= DEPTH-1; // fifio free is initiliazed full
 rd_addr <= 1; //slot 0 is running so is not considered as free - slot 0 assigned by reset of selector
 wr_addr <= 0;
 end else begin
 if (rd_en && !wr_en) begin
 rd_addr <= rd_addr +1;
 if (status_cnt != 0) begin
 status_cnt <= status_cnt -1;
 end
 end else if (wr_en && !rd_en) begin
 ram[wr_addr] <= data_in;
 wr_addr <= wr_addr +1;
 if (status_cnt != DEPTH) begin
 status_cnt <= status_cnt +1;
 end
 end else if (wr_en && rd_en) begin
 rd_addr <= rd_addr +1;
 wr_addr <= wr_addr +1;
 ram[wr_addr] <= data_in;
 end
 end
end

parameter RAM_DEPTH = (1 << ADDR_WIDTH);

reg [ADDR_WIDTH-1:0] wr_pointer;
reg [ADDR_WIDTH-1:0] rd_pointer;
reg [ADDR_WIDTH :0] status_cnt;
reg [BITSIZE_data_in-1:0] data_out ;
wire [BITSIZE_data_in-1:0] data_ram ;

assign full = (status_cnt > (RAM_DEPTH-1));
assign empty = (status_cnt == 0);

always @ (posedge clock 1RESET_EDGE)
begin : WRITE_POINTER
 if (1RESET_VALUE) begin
 wr_pointer <= 0;
 end else if (wr_cs && wr_en ) begin
 wr_pointer <= wr_pointer + 1;
 end
end

always @ (posedge clock 1RESET_EDGE)
begin : READ_POINTER
 if (1RESET_VALUE) begin
 rd_pointer <= 0;
 end else if (rd_cs && rd_en ) begin
 rd_pointer <= rd_pointer + 1;
 end
end

always @ (posedge clock 1RESET_EDGE)
begin : READ_DATA
 if (1RESET_VALUE) begin
 data_out <= 0;
 end else if (rd_cs && rd_en ) begin
 data_out <= data_ram;
 end
end

always @ (posedge clock 1RESET_EDGE)
begin : STATUS_COUNTER
 if (1RESET_VALUE) begin
 status_cnt <= 0;
 end else if ((rd_cs && rd_en) && !(wr_cs && wr_en) 
 && (status_cnt != 0)) begin
 status_cnt <= status_cnt - 1;
 end else if ((wr_cs && wr_en) && !(rd_cs && rd_en) 
 && (status_cnt != RAM_DEPTH)) begin
 status_cnt <= status_cnt + 1;
 end
end

