 out1 <= std_logic_vector(resize(unsigned(proxy_out1), BITSIZE_out1));
 proxy_in1 <= std_logic_vector(resize(unsigned(in1), BITSIZE_proxy_in1)) when (int_sel_STORE /= '0') else (others => '0');
 proxy_in2r <= in2r when (int_sel_LOAD /= '0') else (others => '0');
 proxy_in2w <= in2w when (int_sel_STORE /= '0') else (others => '0');
 proxy_in3r <= in3r when (int_sel_LOAD /= '0') else (others => '0');
 proxy_in3w <= in3w when (int_sel_STORE /= '0') else (others => '0');
 proxy_in4r <= int_sel_LOAD;
 proxy_in4w <= int_sel_STORE;
 proxy_sel_LOAD <= int_sel_LOAD;
 proxy_sel_STORE <= int_sel_STORE;

NP_functionality.VERILOG_PROVIDED:
wire int_sel_LOAD;
wire int_sel_STORE;
assign int_sel_LOAD = sel_LOAD & in4r;
assign int_sel_STORE = sel_STORE & in4w;
assign out1 = proxy_out1;
assign proxy_in1 = int_sel_STORE ? in1 : 0;
assign proxy_in2r = int_sel_LOAD ? in2r : 0;
assign proxy_in2w = int_sel_STORE ? in2w : 0;
assign proxy_in3r = int_sel_LOAD ? in3r : 0;
assign proxy_in3w = int_sel_STORE ? in3w : 0;
assign proxy_in4r = int_sel_LOAD;
assign proxy_in4w = int_sel_STORE;
assign proxy_sel_LOAD = int_sel_LOAD;
assign proxy_sel_STORE = int_sel_STORE;

wire [PORTSIZE_sel_LOAD-1:0] int_sel_LOAD;
wire [PORTSIZE_sel_STORE-1:0] int_sel_STORE;
assign int_sel_LOAD = sel_LOAD & in4r;
assign int_sel_STORE = sel_STORE & in4w;
generate
genvar i0;
for (i0=0; i0<PORTSIZE_out1; i0=i0+1)
 begin : L0
 assign out1[(i0+1)*BITSIZE_out1-1:i0*BITSIZE_out1] = proxy_out1[(i0+1)*BITSIZE_proxy_out1-1:i0*BITSIZE_proxy_out1];
 end
endgenerate
generate
genvar i1;
for (i1=0; i1<PORTSIZE_in1; i1=i1+1)
 begin : L1
 assign proxy_in1[(i1+1)*BITSIZE_proxy_in1-1:i1*BITSIZE_proxy_in1] = int_sel_STORE[i1] ? in1[(i1+1)*BITSIZE_in1-1:i1*BITSIZE_in1] : 0;
 end
endgenerate
generate
genvar i2r;
for (i2r=0; i2r<PORTSIZE_in2r; i2r=i2r+1)
 begin : L2r
 assign proxy_in2r[(i2r+1)*BITSIZE_proxy_in2r-1:i2r*BITSIZE_proxy_in2r] = int_sel_LOAD[i2r] ? in2r[(i2r+1)*BITSIZE_in2r-1:i2r*BITSIZE_in2r] : 0;
 end
endgenerate

generate
genvar i2w;
for (i2w=0; i2w<PORTSIZE_in2w; i2w=i2w+1)
 begin : L2w
 assign proxy_in2w[(i2w+1)*BITSIZE_proxy_in2w-1:i2w*BITSIZE_proxy_in2w] = int_sel_STORE[i2w] ? in2w[(i2w+1)*BITSIZE_in2w-1:i2w*BITSIZE_in2w] : 0;
 end
endgenerate

generate
genvar i3r;
for (i3r=0; i3r<PORTSIZE_in3r; i3r=i3r+1)
 begin : L3r
 assign proxy_in3r[(i3r+1)*BITSIZE_proxy_in3r-1:i3r*BITSIZE_proxy_in3r] = int_sel_LOAD[i3r] ? in3r[(i3r+1)*BITSIZE_in3r-1:i3r*BITSIZE_in3r] : 0;
 end
endgenerate

generate
genvar i3w;
for (i3w=0; i3w<PORTSIZE_in3w; i3w=i3w+1)
 begin : L3w
 assign proxy_in3w[(i3w+1)*BITSIZE_proxy_in3w-1:i3w*BITSIZE_proxy_in3w] = int_sel_STORE[i3w] ? in3w[(i3w+1)*BITSIZE_in3w-1:i3w*BITSIZE_in3w] : 0;
 end
endgenerate

assign proxy_in4r = int_sel_LOAD;
assign proxy_in4w = int_sel_STORE;
assign proxy_sel_LOAD = int_sel_LOAD;
assign proxy_sel_STORE = int_sel_STORE;

localparam [1:0] IDLE = 2'b00;
 localparam [1:0] SEND = 2'b01;
 localparam [1:0] FULL = 2'b10;

 reg selector_out;
 reg std_wenable;
 reg stall_wenable;

 reg [1:0] state, state_next;

 always @(posedge in_clk)
 begin
 state <= state_next;
 if(1RESET_VALUE)
 begin
 state <= IDLE;
 end
 end

 always @(*)
 begin
 state_next = state;
 std_wenable = 0;
 stall_wenable = 0;
 selector_out = 0;
 case (state)
 IDLE :
 begin
 if(valid_in)
 begin
 state_next = SEND;
 std_wenable = 1;
 end
 end
 SEND :
 begin
 if(valid_in ^ ready_in)
 begin
 if(valid_in)
 begin
 state_next = FULL;
 stall_wenable = 1;
 end
 else
 begin
 state_next = IDLE;
 end
 end
 else
 begin
 if(ready_in)
 begin
 std_wenable = 1;
 end
 end
 end
 FULL :
 begin
 selector_out = 1;
 if((!valid_in) << (ready_in))
 begin
 state_next = SEND;
 std_wenable = 1;
 end
 end
 default :
 begin
 state_next = IDLE;
 end
 endcase
 end

 assign valid_out = ((state == SEND) || (state == FULL));
 assign ready_out = ((state == IDLE) || (state == SEND));

localparam HOLD=PIPELINED ? 1'b0 : 1'b1,
 CHANNELS_NUMBER=BITSIZE_S_we_ram,
 BITSIZE_we=1,
 BITSIZE_addr=BITSIZE_S_addr_ram/CHANNELS_NUMBER,
 BITSIZE_Wsize=BITSIZE_S_data_ram_size/CHANNELS_NUMBER,
 BITSIZE_Wdata=BITSIZE_S_Wdata_ram/CHANNELS_NUMBER,
 BITSIZE_ready=1;
reg [bitsize-1:0] val, val_next;
reg we, we_next, waiting, waiting_next, start, start_next;
reg [BITSIZE_addr-1:0] addr, addr_next;
reg [BITSIZE_Wdata-1:0] data, data_next;
reg [BITSIZE_Wsize-1:0] data_size, data_size_next;
wire rdy;

if_utils #(index, bitsize) m_utils();

assign rdy = Sout_DataRdy[0];

assign S_oe_ram = {BITSIZE_S_oe_ram{1'b0}};
assign S_we_ram = {{BITSIZE_S_we_ram-BITSIZE_we{1'b0}}, we_next};
assign S_addr_ram = {{BITSIZE_S_addr_ram-BITSIZE_addr{1'b0}}, addr_next};
assign S_Wdata_ram = {{BITSIZE_S_Wdata_ram-BITSIZE_Wdata{1'b0}}, data_next};
assign S_data_ram_size = {{BITSIZE_S_data_ram_size-BITSIZE_Wsize{1'b0}}, data_size_next};
assign start_port = start;

always @(posedge clock) 
begin
 val <= val_next;
 we <= we_next;
 addr <= addr_next;
 data <= data_next;
 data_size <= data_size_next;
 waiting <= waiting_next;
 start <= start_next;
 if(1RESET_VALUE)
 begin
 val <= 0;
 we <= 0;
 addr <= 0;
 data <= 0;
 data_size <= 0;
 waiting <= 0;
 start <= 0;
 end
 else if(setup_port)
 begin
 val <= m_utils.read();
 end
end

always @(*)
begin
 val_next = val;
 we_next = we & HOLD & waiting & ~rdy;
 addr_next = addr & {BITSIZE_addr{HOLD & waiting & ~rdy}};
 data_next = data & {BITSIZE_Wdata{HOLD & waiting & ~rdy}};
 data_size_next = data_size & {BITSIZE_Wsize{HOLD & waiting & ~rdy}};
 waiting_next = waiting & ~rdy;
 start_next = waiting & rdy;
 if(i_start_port)
 begin
 we_next = 1;
 addr_next = tgt_addr;
 data_next = {{BITSIZE_Wdata-bitsize{1'b0}}, val};
 data_size_next = bitsize;
 waiting_next = ~rdy;
 start_next = rdy;
 end
end

localparam bytesize=((bitsize>>3)<<3) == bitsize ? (bitsize>>3) : ((bitsize>>3) + 1);
reg [bitsize-1:0] val;
wire [bitsize-1:0] val_next;
reg cyc, cyc_next, stb, stb_next, we, we_next, stall, ack, start;
reg [BITSIZE_addr_is-1:0] addr, addr_next;
reg [BITSIZE_dat_is-1:0] data, data_next;
reg [BITSIZE_sel_is-1:0] sel, sel_next;

if_utils #(index, bitsize) m_utils();

initial
begin
 val = 0;
 cyc = 0;
 cyc_next = 0;
 stb = 0;
 stb_next = 0;
 we = 0;
 we_next = 0;
 addr = 0;
 addr_next = 0;
 data = 0;
 data_next = 0;
 sel = 0;
 sel_next = 0;
 start = 0;
end

assign cyc_is = cyc_next;
assign stb_is = stb_next;
assign we_is = we_next;
assign addr_is = addr_next;
assign dat_is = data_next;
assign sel_is = sel_next;
assign stall = ~ack_os; // TODO: this should be stall_os
assign ack = ack_os;
assign start_port = start;

always @(posedge clock) 
begin
 automatic reg active_tx = cyc_next & ~ack;
 automatic reg wait_tx = active_tx & stall;
 val <= val_next;
 cyc <= active_tx;
 stb <= stb_next & wait_tx;
 we <= we_next & wait_tx;
 addr <= addr_next & {BITSIZE_addr_is{wait_tx}};
 data <= data_next & {BITSIZE_dat_is{wait_tx}};
 sel <= sel_next & {BITSIZE_sel_is{wait_tx}};
 start <= ack & cyc_next;
 if(setup_port)
 begin
 val <= m_utils.read();
 end
end

assign val_next = val;

always @(*)
begin
 cyc_next = cyc;
 stb_next = stb;
 we_next = we;
 addr_next = addr;
 data_next = data;
 sel_next = sel;
 if(i_start_port)
 begin
 cyc_next = 1;
 stb_next = 1;
 we_next = 1;
 addr_next = tgt_addr;
 data_next[bitsize-1:0] = val;
 sel_next = {bytesize{1'b1}};
 end
end

localparam CHANNELS_NUMBER=PORTSIZE_ce,
 BITSIZE_dq=BITSIZE_d > BITSIZE_q ? BITSIZE_d : BITSIZE_q,
 BITSIZE_item=BITSIZE_d+BITSIZE_address+BITSIZE_ce+BITSIZE_we,
 BITSIZE_chunk=BITSIZE_item*CHANNELS_NUMBER,
 OFFSET_ce=0,
 OFFSET_we=OFFSET_ce+BITSIZE_ce,
 OFFSET_address=OFFSET_we+BITSIZE_we,
 OFFSET_data=OFFSET_address+BITSIZE_address,
 LAST_READ_item=READ_DELAY > 1 ? READ_DELAY-2 : 0,
 LAST_READ_size=READ_DELAY > 1 ? READ_DELAY-1 : 1;
genvar i;

if_utils #(index, BITSIZE_dq) m_utils();

wire [BITSIZE_chunk-1:0] current;
reg [BITSIZE_chunk*WRITE_DELAY-1:0] queue = 0, queue_next = 0;
reg [CHANNELS_NUMBER*BITSIZE_q*LAST_READ_size-1:0] _q_next = 0;
reg [CHANNELS_NUMBER*BITSIZE_q*LAST_READ_size-1:0] _q = 0;

generate
 for(i = 0; i < CHANNELS_NUMBER; i = i + 1)
 begin
 assign current[BITSIZE_item*i+:BITSIZE_item] = {d[BITSIZE_d*i+:BITSIZE_d], address[BITSIZE_address*i+:BITSIZE_address], we[BITSIZE_we*i+:BITSIZE_we], ce[BITSIZE_ce*i+:BITSIZE_ce]};
 assign q[BITSIZE_q*i+:BITSIZE_q] = _q[LAST_READ_item*BITSIZE_q*CHANNELS_NUMBER+BITSIZE_q*i+:BITSIZE_q];
 end
endgenerate

generate
 if(WRITE_DELAY > 1)
 begin
 always @(posedge clock)
 begin
 if(setup_port)
 begin
 queue[BITSIZE_chunk*WRITE_DELAY-1:BITSIZE_chunk] <= 0;
 queue[BITSIZE_chunk-1:0] <= current;
 end
 else
 begin
 queue[BITSIZE_chunk*WRITE_DELAY-1:BITSIZE_chunk] <= queue_next[BITSIZE_chunk*WRITE_DELAY-1:BITSIZE_chunk];
 queue[BITSIZE_chunk-1:0] <= current;
 end
 end
 always @(*)
 begin
 queue_next[BITSIZE_chunk*WRITE_DELAY-1:BITSIZE_chunk] = queue[BITSIZE_chunk*(WRITE_DELAY-1)-1:0];
 queue_next[BITSIZE_chunk-1:0] = 0;
 end
 end
endgenerate

generate
 for(i = 0; i < CHANNELS_NUMBER; i = i + 1)
 begin : write_port
 if(WRITE_DELAY > 1)
 begin
 always @(posedge clock)
 begin
 automatic ptr_t address = queue_next[(WRITE_DELAY-1)*BITSIZE_chunk+BITSIZE_item*i+OFFSET_address+:BITSIZE_address];
 automatic reg [BITSIZE_d-1:0] data = queue_next[(WRITE_DELAY-1)*BITSIZE_chunk+BITSIZE_item*i+OFFSET_data+:BITSIZE_d];
 if(queue_next[(WRITE_DELAY-1)*BITSIZE_chunk+BITSIZE_item*i+OFFSET_ce+:BITSIZE_ce] === 1'b1
 && queue_next[(WRITE_DELAY-1)*BITSIZE_chunk+BITSIZE_item*i+OFFSET_we+:BITSIZE_we] === 1'b1)
 begin
 void'(m_utils.write_a(data, address));
 end
 end
 end
 else
 begin
 always @(posedge clock)
 begin
 automatic ptr_t address = current[BITSIZE_item*i+OFFSET_address+:BITSIZE_address];
 automatic reg [BITSIZE_d-1:0] data = current[BITSIZE_item*i+OFFSET_data+BITSIZE_d-1:BITSIZE_item*i+OFFSET_data];
 if(current[BITSIZE_item*i+OFFSET_ce+:BITSIZE_ce] === 1'b1 && current[BITSIZE_item*i+OFFSET_we+:BITSIZE_we] === 1'b1)
 begin
 void'(m_utils.write_a(data, address));
 end
 end
 end
 end
endgenerate

generate
 if(READ_DELAY > 2)
 begin : shift_output_queue1
 always @(*)
 begin
 _q_next[(READ_DELAY-1)*CHANNELS_NUMBER*BITSIZE_q-1:BITSIZE_q*CHANNELS_NUMBER] = _q[LAST_READ_item*CHANNELS_NUMBER*BITSIZE_q-1:0];
 end
 end
endgenerate
generate
 if(READ_DELAY > 2)
 begin : shift_output_queue2
 always @(posedge clock)
 begin
 _q[(READ_DELAY-1)*CHANNELS_NUMBER*BITSIZE_q-1:BITSIZE_q*CHANNELS_NUMBER] <= _q_next[(READ_DELAY-1)*CHANNELS_NUMBER*BITSIZE_q-1:BITSIZE_q*CHANNELS_NUMBER];
 end
 end
endgenerate
generate
 for(i = 0; i < CHANNELS_NUMBER; i = i + 1)
 begin : read_port
 if(READ_DELAY > 1)
 begin
 always @(posedge clock)
 begin
 if(current[BITSIZE_item*i+OFFSET_ce+:BITSIZE_ce] === 1'b1
 && current[BITSIZE_item*i+OFFSET_we+:BITSIZE_we] === 1'b0)
 begin
 automatic ptr_t address = current[BITSIZE_item*i+OFFSET_address+:BITSIZE_address];
 _q[BITSIZE_q*i+:BITSIZE_q] <= m_utils.read_a(address);
 end
 else
 begin
 _q[BITSIZE_q*i+:BITSIZE_q] <= 0;
 end
 end
 end
 else
 begin
 always @(*)
 begin
 if(current[BITSIZE_item*i+OFFSET_ce+:BITSIZE_ce] === 1'b1 && current[BITSIZE_item*i+OFFSET_we+:BITSIZE_we] === 1'b0)
 begin
 automatic ptr_t address = current[BITSIZE_item*i+OFFSET_address+:BITSIZE_address];
 _q[BITSIZE_q*i+:BITSIZE_q] = m_utils.read_a(address);
 end
 end
 end
 end
endgenerate

`ifdef VERILATOR
timeunit 1ps;
timeprecision 1ps;
`endif

import "DPI-C" function int unsigned m_next(input int unsigned state);
import "DPI-C" function int m_fini();

localparam [6:0] 
 STATE_READY =7'b0000001,
 STATE_SETUP =7'b0000010,
 STATE_RUNNING =7'b0000100,
 STATE_END =7'b0001000,
 STATE_ERROR =7'b0010000,
 STATE_ABORT =7'b0100000,
 SIM_DONE =7'b1000000;
reg [$bits(STATE_READY)-1:0] state, state_next, state_succ, state_succ_next;

reg rst, rst_next, setup, setup_next, start, start_next;
integer rst_count, rst_count_next;
time over_time;

initial
begin
 // Open file results will be written
 automatic integer res_file;
 res_file = $fopen(RESFILE, "w");
 if (res_file == 0)
 begin
 $display("ERROR - Error opening the res_file");
 $finish;// Terminate
 end
 $fwrite(res_file, "");
 $fclose(res_file);

 state = STATE_READY;
 state_next = STATE_READY;
 state_succ = STATE_READY;
 state_succ_next = STATE_READY;
 rst = RESET_ACTIVE;
 rst_next = RESET_ACTIVE;
 rst_count = RESET_CYCLES;
 rst_count_next = RESET_CYCLES;
 setup = 0;
 setup_next = 0;
 start = 0;
 start_next = 0;
 over_time = 0;

 $display("Results file: %s", RESFILE);
 $display("Reset active: %0s", RESET_ACTIVE ? "HIGH" : "LOW");
end

assign reset = rst;
assign setup_port = setup;
assign start_port = start;

always @(posedge clock)
begin
 state <= state_next;
 state_succ <= state_succ_next;
 rst <= rst_next;
 rst_count <= rst_count_next;
 setup <= setup_next;
 start <= start_next;
 case(state_next)
 STATE_READY:
 begin
 automatic integer unsigned next_state = m_next(STATE_READY);
 `ifndef NDEBUG
 $display("Sim: next state: %0d (retval: %0d)", next_state[$bits(state_succ)-1:0], next_state[15:8]);
 `endif
 state_succ <= next_state[$bits(state_succ)-1:0];
 end
 STATE_SETUP:
 begin
 automatic time start_time = $time + CLOCK_PERIOD;
 automatic time start_cycle = $rtoi($itor(start_time)/CLOCK_PERIOD);
 automatic integer res_file;
 if(setup_next)
 begin
 res_file = $fopen(RESFILE, "a");
 $fwrite(res_file, "%0d|", start_time);
 $fclose(res_file);
 `ifndef NDEBUG
 $display("Sim: Argument setup
Sim: Simulation started at cycle %0d", start_cycle);
 `endif
 end
 over_time <= start_cycle + MAX_SIM_CYCLES;
 end
 STATE_RUNNING:
 begin
 automatic time curr_cycle = $rtoi($itor($time)/CLOCK_PERIOD);
 if(curr_cycle >= over_time)
 begin
 automatic integer res_file;
 res_file = $fopen(RESFILE, "a");
 $fwrite(res_file, "X");
 $fclose(res_file);
 $display("Sim: Simulation exceeds %0d cycles", MAX_SIM_CYCLES);
 $finish;
 end
 end
 SIM_DONE:
 begin
 automatic time curr_time = $time;
 automatic time curr_cycle = $rtoi($itor(curr_time)/CLOCK_PERIOD);
 automatic integer res_file;
 res_file = $fopen(RESFILE, "a");
 $fwrite(res_file, "%0d,", curr_time);
 $fclose(res_file);
 `ifndef NDEBUG
 $display("Sim: DUT port writeback
Sim: Simulation ended at cycle %0d", curr_cycle);
 `endif
 end
 STATE_END:
 begin
 automatic integer r = m_fini();
 automatic integer res_file;
 res_file = $fopen(RESFILE, "a");
 $fwrite(res_file, "
%0d
", r[15:8]);
 $display("Sim: Testbench returned: %0d", r[15:8]);
 $fclose(res_file);
 $finish;
 end
 STATE_ABORT:
 begin
 automatic integer r = m_fini();
 automatic integer res_file;
 res_file = $fopen(RESFILE, "a");
 $fwrite(res_file, "
A
");
 $display("Sim: Testbench aborted");
 $fclose(res_file);
 $finish;
 end
 default:
 begin
 end
 endcase
end

always @(*)
begin
 rst_next = rst;
 rst_count_next = rst_count;
 setup_next = setup;
 start_next = start;
 state_next = state;
 state_succ_next = state_succ;
 case(state)
 STATE_READY:
 begin
 state_next = state_succ;
 if(state_succ == STATE_SETUP)
 begin
 if(RESET_ALWAYS || rst_count > 0)
 begin
 rst_next = RESET_ACTIVE;
 rst_count_next = RESET_CYCLES;
 end
 else
 begin
 rst_count_next = 1;
 end
 end
 end
 STATE_SETUP:
 begin
 if(rst_count > 1)
 begin
 setup_next = rst_count == 0;
 rst_next = RESET_ACTIVE;
 rst_count_next = rst_count - 1;
 end
 else if(rst_count == 1)
 begin
 setup_next = 1;
 rst_next = ~RESET_ACTIVE;
 rst_count_next = 0;
 end
 else
 begin
 state_next = STATE_RUNNING;
 setup_next = 0;
 start_next = 1;
 end
 end
 STATE_RUNNING:
 begin
 start_next = 0;
 if(done_port)
 begin
 state_next = SIM_DONE;
 end
 end
 SIM_DONE:
 begin
 // A clock cycle must pass to allow interface modules 
 // finalization operations
 state_next = STATE_READY;
 end
 STATE_END:
 begin
 end
 STATE_ABORT:
 begin
 end
 default:
 begin
 state_next = STATE_READY;
 end
 endcase
end

if_utils #(index, BITSIZE_dout) m_utils();

reg enable, enable_next;
reg _empty_n, _empty_n_next;
reg [BITSIZE_dout-1:0] val, val_next;

initial
begin
 enable = 0;
 _empty_n = 0;
 val = 0;
end

assign dout = val;
assign empty_n = _empty_n;

always @(posedge clock)
begin
 enable <= enable_next;
 _empty_n <= _empty_n_next;
 val <= val_next;
 if(setup_port)
 begin
 automatic int data = 0;
 val <= m_utils.read_i(data);
 _empty_n <= data > 0;
 enable <= 1'b1;
 end
 else if((enable_next | done_port) & read)
 begin
 automatic int data = 0;
 if(~_empty_n_next)
 begin
 $display("Too many read requests on interface %0d", index);
 $finish;
 end
 val <= m_utils.pop(data);
 _empty_n <= data > 0;
 end
end

always @(*)
begin
 enable_next = enable & ~done_port;
 _empty_n_next = _empty_n;
 val_next = val;
end

generate
 if(CHECK_ACK)
 begin
 reg ack_check, ack_check_next;
 initial ack_check = 0;
 assign ack_check_next = read | ack_check;
 always @(posedge clock)
 begin
 ack_check <= ack_check_next;
 if(setup_port)
 begin
 ack_check <= 0;
 end
 if(done_port & ~ack_check_next)
 begin
 $display("WARNING: Acknowledge signal never asserted on interface %0d.", index);
 end
 end
 end
endgenerate

if_utils #(index, BITSIZE_din) m_utils();

reg enable, enable_next;
reg _full_n, _full_n_next;

initial
begin
 enable = 0;
 _full_n = 0;
end

assign full_n = _full_n;

always @(posedge clock)
begin
 enable <= enable_next;
 _full_n <= _full_n_next;
 if(setup_port)
 begin
 automatic int data = 0;
 data = m_utils.state(4);
 _full_n <= data > 0;
 enable <= 1'b1;
 end
 if((enable_next | done_port) & write)
 begin
 automatic int data = 0;
 data = m_utils.push(din);
 _full_n <= data > 0;
 if(data < 0)
 begin
 $display("Too many write requests on interface %0d", index);
 $finish;
 end
 end
end

always @(*) 
begin
 enable_next = enable & ~done_port;
 _full_n_next = _full_n;
end

function automatic integer log2;
 input integer value;
 `ifdef _SIM_HAVE_CLOG2
 log2 = $clog2(value);
 `else
 automatic integer temp_value = value-1;
 for (log2=0; temp_value > 0; log2=log2+1)
 temp_value = temp_value >> 1;
 `endif
endfunction

localparam MEM_DELAY_MAX= MEM_DELAY_READ > MEM_DELAY_WRITE ? MEM_DELAY_READ : MEM_DELAY_WRITE,
 ACTIVE_READ= MEM_DELAY_READ > 1 ? (MEM_DELAY_READ-2) : 0,
 ACTIVE_WRITE= MEM_DELAY_WRITE > 1 ? (MEM_DELAY_WRITE-2) : 0,
 CHANNELS_NUMBER=BITSIZE_Mout_oe_ram,
 BITSIZE_oe=1,
 BITSIZE_we=1,
 BITSIZE_addr=BITSIZE_Mout_addr_ram/CHANNELS_NUMBER,
 BITSIZE_Wsize=BITSIZE_Mout_data_ram_size/CHANNELS_NUMBER,
 BITSIZE_Wdata=BITSIZE_Mout_Wdata_ram/CHANNELS_NUMBER,
 BITSIZE_ready=1,
 BITSIZE_Rdata=BITSIZE_M_Rdata_ram/CHANNELS_NUMBER,
 BITSIZE_item=BITSIZE_Wdata+BITSIZE_Wsize+BITSIZE_addr+BITSIZE_we+BITSIZE_oe,
 OFFSET_oe=0,
 OFFSET_we=OFFSET_oe+BITSIZE_oe,
 OFFSET_addr=OFFSET_we+BITSIZE_we,
 OFFSET_Wsize=OFFSET_addr+BITSIZE_addr,
 OFFSET_Wdata=OFFSET_Wsize+BITSIZE_Wsize,
 BITSIZE_S_Rdata=BITSIZE_Sout_Rdata_ram/BITSIZE_S_oe_ram,
 BITSIZE_S_ready=1,
 SLAVE_VALID=BITSIZE_Mout_oe_ram == BITSIZE_S_oe_ram,
 QUEUE_BITSIZE=QUEUE_SIZE > 1 ? log2(QUEUE_SIZE) : 1;

genvar i;
integer dump_file;
wire [BITSIZE_M_DataRdy-1:0] _M_DataRdy, _M_DataRdy_reg;
wire [BITSIZE_M_Rdata_ram-1:0] _M_Rdata_ram;

assign S_oe_ram = Mout_oe_ram;
assign S_we_ram = Mout_we_ram;
assign S_addr_ram = Mout_addr_ram;
assign S_data_ram_size = Mout_data_ram_size;
assign S_Wdata_ram = Mout_Wdata_ram;
assign M_DataRdy = _M_DataRdy;
assign M_Rdata_ram = _M_Rdata_ram;

generate
 if(MEM_DUMP)
 begin
 initial
 begin
 dump_file = $fopen(MEM_DUMP_FILE, "w");
 $fwrite(dump_file, "Channel,Operation,Address,Bitwidth,Data
");
 end

 always@(posedge clock)
 begin
 if(done_port)
 begin
 $fflush(dump_file);
 end
 end
 end
endgenerate

if_utils #(index, BITSIZE_Rdata) m_utils();

generate
 for(i = 0; i < CHANNELS_NUMBER; i = i + 1)
 begin : channel
 wire [MEM_DELAY_MAX*BITSIZE_item-1:0] queue_next;
 wire [BITSIZE_oe-1:0] oe;
 wire [BITSIZE_we-1:0] we;
 ptr_t Waddr, Raddr;
 shortint unsigned Wsize;
 wire [BITSIZE_Wdata-1:0] Wdata;
 reg [BITSIZE_ready-1:0] Wready, Rready, Wready_reg;
 reg [BITSIZE_Rdata-1:0] Rdata;

 reg [QUEUE_BITSIZE-1:0] queue_counter;
 wire [QUEUE_BITSIZE-1:0] queue_counter_next;

 if(MEM_DELAY_WRITE == 1)
 begin
 always@(posedge clock)
 begin
 Wready_reg <= Wready;
 end
 end
 else
 begin
 assign Wready_reg = Wready;
 end
 if(QUEUE_SIZE > 1)
 begin
 assign Mout_back_pressure[i] = queue_counter == 0 ? 0 : (queue_counter - _M_DataRdy_reg[BITSIZE_ready*i+:BITSIZE_ready]) == (QUEUE_SIZE - 1);
 end
 else
 begin
 assign Mout_back_pressure[i] = queue_counter && !_M_DataRdy_reg[BITSIZE_ready*i+:BITSIZE_ready];
 end

 always @(posedge clock)
 begin
 if(1RESET_VALUE)
 begin
 queue_counter <= 0;
 end
 else
 begin
 queue_counter <= queue_counter_next;
 end
 end

 if(QUEUE_SIZE > 1)
 begin
 assign queue_counter_next = queue_counter + (((Mout_we_ram[i] || Mout_oe_ram[i]) && !Mout_back_pressure[i] && base_addr <= Mout_addr_ram[i*BITSIZE_addr +: BITSIZE_addr]) && (queue_counter == 0 ? 1 : ((queue_counter - _M_DataRdy_reg[BITSIZE_ready*i+:BITSIZE_ready]) < (QUEUE_SIZE - 1)))) - _M_DataRdy_reg[BITSIZE_ready*i+:BITSIZE_ready];
 end
 else
 begin
 assign queue_counter_next = ((Mout_we_ram[i] || Mout_oe_ram[i]) && !Mout_back_pressure[i] && base_addr <= Mout_addr_ram[i*BITSIZE_addr +: BITSIZE_addr]) || (queue_counter && !_M_DataRdy_reg[BITSIZE_ready*i+:BITSIZE_ready]);
 end


 if(MEM_DELAY_MAX > 1)
 begin : requests_queue
 reg [MEM_DELAY_MAX*BITSIZE_item-1:0] queue;
 wire [BITSIZE_item-1:0] new_elem;

 assign new_elem = Mout_back_pressure[i] ? {BITSIZE_item{1'b0}} : 
 {Mout_Wdata_ram[BITSIZE_Wdata*i+:BITSIZE_Wdata],
 Mout_data_ram_size[BITSIZE_Wsize*i+:BITSIZE_Wsize],
 Mout_addr_ram[BITSIZE_addr*i+:BITSIZE_addr],
 Mout_we_ram[BITSIZE_we*i+:BITSIZE_we],
 Mout_oe_ram[BITSIZE_oe*i+:BITSIZE_oe]};

 assign queue_next = {queue[(MEM_DELAY_MAX-1)*BITSIZE_item-1:0],new_elem};

 always@(posedge clock)
 begin
 if(1RESET_VALUE)
 begin
 queue <= 0;
 end
 else
 begin
 queue <= queue_next;
 end
 end
 end
 else
 begin
 assign queue_next = {Mout_Wdata_ram[BITSIZE_Wdata*i+:BITSIZE_Wdata], 
 Mout_data_ram_size[BITSIZE_Wsize*i+:BITSIZE_Wsize],
 Mout_addr_ram[BITSIZE_addr*i+:BITSIZE_addr],
 Mout_we_ram[BITSIZE_we*i+:BITSIZE_we],
 Mout_oe_ram[BITSIZE_oe*i+:BITSIZE_oe]};
 end

 assign oe = queue_next[ACTIVE_READ*BITSIZE_item+OFFSET_oe+:BITSIZE_oe];
 assign Raddr = queue_next[ACTIVE_READ*BITSIZE_item+OFFSET_addr+:BITSIZE_addr];
 assign _M_DataRdy[BITSIZE_ready*i+:BITSIZE_ready] = Wready | Rready | (Sout_DataRdy[BITSIZE_S_ready*i*SLAVE_VALID+:BITSIZE_S_ready] === 1'b1);
 assign _M_DataRdy_reg[BITSIZE_ready*i+:BITSIZE_ready] = Wready_reg | Rready; // Used to update at posedge clock of the queue_counter;
 assign _M_Rdata_ram[BITSIZE_Rdata*i+:BITSIZE_Rdata] = Rdata | (Sout_Rdata_ram[BITSIZE_S_Rdata*i*SLAVE_VALID+:BITSIZE_S_Rdata] & {BITSIZE_S_Rdata{Sout_DataRdy[BITSIZE_S_ready*i*SLAVE_VALID+:BITSIZE_S_ready] === 1'b1}});

 if(MEM_DELAY_READ > 1)
 begin : read_channel
 always@(posedge clock)
 begin : read_channel
 automatic reg [BITSIZE_Rdata-1:0] data;
 Rready <= 0;
 Rdata <= 0;
 if(oe && base_addr <= Raddr)
 begin
 data = m_utils.read_a(Raddr);
 Rdata <= data;
 Rready <= 1;
 if(MEM_DUMP)
 begin
 $fwrite(dump_file, "%0d,r,%0X,%0d,%0X
", i, Raddr, BITSIZE_Rdata, data);
 end
 end
 end
 end
 else
 begin
 always@(negedge clock)
 begin : read_channel
 automatic reg [BITSIZE_Rdata-1:0] data;
 Rready <= 0;
 Rdata <= 0;
 if(oe && base_addr <= Raddr)
 begin
 data = m_utils.read_a(Raddr);
 Rdata <= data;
 Rready <= 1;
 if(MEM_DUMP)
 begin
 $fwrite(dump_file, "%0d,r,%0X,%0d,%0X
", i, Raddr, BITSIZE_Rdata, data);
 end
 end
 end
 end

 assign we = queue_next[ACTIVE_WRITE*BITSIZE_item+OFFSET_we+:BITSIZE_we];
 assign Waddr = queue_next[ACTIVE_WRITE*BITSIZE_item+OFFSET_addr+:BITSIZE_addr];
 assign Wsize = {{16-BITSIZE_Wsize{1'b0}}, queue_next[ACTIVE_WRITE*BITSIZE_item+OFFSET_Wsize+:BITSIZE_Wsize]};
 assign Wdata = queue_next[ACTIVE_WRITE*BITSIZE_item+OFFSET_Wdata+:BITSIZE_Wdata];

 if(MEM_DELAY_WRITE > 1)
 begin : write_channel
 always@(posedge clock)
 begin : write_channel
 Wready <= 0;
 if(we && base_addr <= Waddr)
 begin
 void'(m_utils.write_sa(Wdata, Wsize, Waddr));
 Wready <= 1;
 if(MEM_DUMP)
 begin
 $fwrite(dump_file, "%0d,w,%0X,%0d,%0X
", i, Waddr, Wsize, Wdata);
 end
 end
 end
 end
 else
 begin
 always@(negedge clock)
 begin : write_channel
 Wready <= 0;
 if(we && base_addr <= Waddr)
 begin
 void'(m_utils.write_sa(Wdata, Wsize, Waddr));
 Wready <= 1;
 if(MEM_DUMP)
 begin
 $fwrite(dump_file, "%0d,w,%0X,%0d,%0X
", i, Waddr, Wsize, Wdata);
 end
 end
 end
 end

 always @(posedge clock)
 begin
 if (we & oe)
 begin
 $display("ERROR - Mout_we_ram and Mout_oe_ram both enabled on channel %0d!", i);
 $finish;
 end
 end
 end
endgenerate

localparam MEM_DELAY_MAX= MEM_DELAY_READ > MEM_DELAY_WRITE ? MEM_DELAY_READ : MEM_DELAY_WRITE,
 BITSIZE_item=BITSIZE_dat_im+1+1;
reg cyc, stb, we, stall, ack;
reg [BITSIZE_addr_om-1:0] addr;
reg [BITSIZE_dat_om-1:0] Wdata;
reg [7:0] size;
reg [BITSIZE_dat_im-1:0] Rdata;

reg [MEM_DELAY_MAX*BITSIZE_item-1:0] queue, queue_next;

if_utils #(index, BITSIZE_dat_im) m_utils();

initial
begin
 stall = 0;
 ack = 0;
 Rdata = 0;
 queue = 0;
end

assign cyc_is = 0;
assign stb_is = 0;
assign addr_is = 0;
assign dat_is = 0;
assign sel_is = 0;

assign cyc = cyc_om;
assign stb = stb_om;
assign we = we_om;
assign addr = addr_om;
assign Wdata = dat_om;
assign size = sel_om;
assign stall_im = stall; // & cyc
assign ack_im = ack; // & cyc
assign dat_im = Rdata; // & {BITSIZE_dat_im{cyc}};

always @(posedge clock)
begin
 automatic reg w_ack = queue_next[(MEM_DELAY_WRITE-1)*BITSIZE_item] & queue_next[(MEM_DELAY_WRITE-1)*BITSIZE_item+1];
 automatic reg r_ack = queue_next[(MEM_DELAY_READ-1)*BITSIZE_item] & ~queue_next[(MEM_DELAY_READ-1)*BITSIZE_item+1];
 ack <= w_ack | r_ack;
 Rdata <= queue_next[(MEM_DELAY_READ-1)*BITSIZE_item+2 +:BITSIZE_dat_im];
 queue <= queue_next;
end

always @(*)
begin
 queue_next = {queue[(MEM_DELAY_MAX-1)*BITSIZE_item-1:0], {BITSIZE_dat_im{1'b0}}, 1'b0, 1'b0};
 if(cyc & stb)
 begin
 queue_next[1:0] = {we, 1'b1};
 end
end

always @(negedge clock)
begin
 if(queue_next[0])
 begin
 automatic ptr_t ptr_addr = addr;
 if(queue_next[1])
 begin
 void'(m_utils.write_strobe(Wdata, sel_om, ptr_addr));
 end
 else
 begin
 queue_next[BITSIZE_item-1:2] <= m_utils.read_a(ptr_addr);
 end
 end
end

localparam HOLD=PIPELINED ? 1'b0 : 1'b1,
 CHANNELS_NUMBER=BITSIZE_S_oe_ram,
 BITSIZE_oe=1,
 BITSIZE_addr=BITSIZE_S_addr_ram/CHANNELS_NUMBER,
 BITSIZE_ready=1,
 BITSIZE_Rdata=BITSIZE_Sout_Rdata_ram/CHANNELS_NUMBER;
reg oe, oe_next, waiting, waiting_next, done, done_next;
reg [BITSIZE_addr-1:0] addr, addr_next;
wire rdy;

if_utils #(index, bitsize) m_utils();

assign rdy = Sout_DataRdy[0];

assign S_oe_ram = {BITSIZE_S_oe_ram-BITSIZE_oe{1'b0}, oe_next};
assign S_we_ram = {BITSIZE_S_we_ram{1'b0}};
assign S_addr_ram = {{BITSIZE_S_addr_ram-BITSIZE_addr{1'b0}}, addr_next};
assign S_Wdata_ram = {BITSIZE_S_Wdata_ram{1'b0}};
assign S_data_ram_size = {BITSIZE_S_data_ram_size{1'b0}};
assign start_port = i_start_port;
assign done_port = done;

always @(posedge clock) 
begin
 oe <= oe_next;
 addr <= addr_next;
 waiting <= waiting_next;
 done <= done_next;
 if(1RESET_VALUE)
 begin
 oe <= 0;
 addr <= 0;
 waiting <= 0;
 done <= 0;
 end
 else if(done_next)
 begin
 void'(m_utils.write(Sout_Rdata_ram[BITSIZE_Rdata-1:0]));
 end
end

always @(*)
begin
 oe_next = oe & HOLD & waiting & ~rdy;
 addr_next = addr & {BITSIZE_addr{HOLD & waiting & ~rdy}};
 waiting_next = waiting & ~rdy;
 done_next = waiting & rdy;
 if(i_done_port)
 begin
 oe_next = 1;
 addr_next = tgt_addr;
 waiting_next = ~rdy;
 done_next = rdy;
 end
end

localparam bytesize=((bitsize>>3)<<3) == bitsize ? (bitsize>>3) : ((bitsize>>3) + 1);
reg cyc, cyc_next, stb, stb_next, stall, ack, done;
reg [BITSIZE_addr_is-1:0] addr, addr_next;

if_utils #(index, bitsize) m_utils();

initial
begin
 cyc = 0;
 cyc_next = 0;
 stb = 0;
 stb_next = 0;
 addr = 0;
 addr_next = 0;
 done = 0;
end

assign cyc_is = cyc_next;
assign stb_is = stb_next;
assign we_is = 0;
assign addr_is = addr_next;
assign dat_is = 0;
assign sel_is = 0;
assign stall = ~ack_os; // TODO: this should be stall_os
assign ack = ack_os;
assign start_port = i_start_port;
assign done_port = done;

always @(posedge clock) 
begin
 automatic reg active_tx = cyc_next & ~ack;
 automatic reg wait_tx = active_tx & stall;
 cyc <= active_tx;
 stb <= stb_next & wait_tx;
 addr <= addr_next & {BITSIZE_addr_is{wait_tx}};
 done <= ack & cyc_next;
 if(ack & cyc_next)
 begin
 void'(m_utils.write(dat_os));
 end
end

always @(*)
begin
 cyc_next = cyc;
 stb_next = stb;
 addr_next = addr;
 if(i_done_port)
 begin
 cyc_next = 1;
 stb_next = 1;
 addr_next = tgt_addr;
 end
end

localparam HOLD=PIPELINED ? 1'b0 : 1'b1,
 CHANNELS_NUMBER=BITSIZE_S_we_ram,
 BITSIZE_we=1,
 BITSIZE_addr=BITSIZE_S_addr_ram/CHANNELS_NUMBER,
 BITSIZE_Wsize=BITSIZE_S_data_ram_size/CHANNELS_NUMBER,
 BITSIZE_Wdata=BITSIZE_S_Wdata_ram/CHANNELS_NUMBER,
 BITSIZE_ready=1;
reg we, we_next, waiting, waiting_next, start, start_next;
reg [BITSIZE_addr-1:0] addr, addr_next;
reg [BITSIZE_Wdata-1:0] data, data_next;
reg [BITSIZE_Wsize-1:0] data_size, data_size_next;
wire rdy;

assign rdy = Sout_DataRdy[0];

assign S_oe_ram = {BITSIZE_S_oe_ram{1'b0}};
assign S_we_ram = {{BITSIZE_S_we_ram-BITSIZE_we{1'b0}}, we_next};
assign S_addr_ram = {{BITSIZE_S_addr_ram-BITSIZE_addr{1'b0}}, addr_next};
assign S_Wdata_ram = {{BITSIZE_S_Wdata_ram-BITSIZE_Wdata{1'b0}}, data_next};
assign S_data_ram_size = {{BITSIZE_S_data_ram_size-BITSIZE_Wsize{1'b0}}, data_size_next};
assign start_port = start;

always @(posedge clock) 
begin
 we <= we_next;
 addr <= addr_next;
 data <= data_next;
 data_size <= data_size_next;
 waiting <= waiting_next;
 start <= start_next;
 if(1RESET_VALUE)
 begin
 we <= 0;
 addr <= 0;
 data <= 0;
 data_size <= 0;
 waiting <= 0;
 start <= 0;
 end
end

always @(*)
begin
 we_next = we & HOLD & waiting & ~rdy;
 addr_next = addr & {BITSIZE_addr{HOLD & waiting & ~rdy}};
 data_next = data & {BITSIZE_Wdata{HOLD & waiting & ~rdy}};
 data_size_next = data_size & {BITSIZE_Wsize{HOLD & waiting & ~rdy}};
 waiting_next = waiting & ~rdy;
 start_next = waiting & rdy;
 if(i_start_port)
 begin
 we_next = 1;
 addr_next = tgt_addr;
 data_next = 1;
 data_size_next = 1;
 waiting_next = ~rdy;
 start_next = rdy;
 end
end

localparam bytesize=1;
reg cyc, cyc_next, stb, stb_next, we, we_next, stall, ack, start;
reg [BITSIZE_addr_is-1:0] addr, addr_next;
reg [BITSIZE_dat_is-1:0] data, data_next;
reg [BITSIZE_sel_is-1:0] sel, sel_next;

initial
