assign stb_is = stb_next;
assign we_is = we_next;
assign addr_is = addr_next;
assign dat_is = data_next;
assign sel_is = sel_next;
assign stall = ~ack_os; // TODO: this should be stall_os
assign ack = ack_os;
assign start_port = start;

always @(posedge clock) 
begin
 automatic reg active_tx = cyc_next & ~ack;
 automatic reg wait_tx = active_tx & stall;
 cyc <= active_tx;
 stb <= stb_next & wait_tx;
 we <= we_next & wait_tx;
 addr <= addr_next & {BITSIZE_addr_is{wait_tx}};
 data <= data_next & {BITSIZE_dat_is{wait_tx}};
 sel <= sel_next & {BITSIZE_sel_is{wait_tx}};
 start <= ack & cyc_next;
end

always @(*)
begin
 cyc_next = cyc;
 stb_next = stb;
 we_next = we;
 addr_next = addr;
 data_next = data;
 sel_next = sel;
 if(i_start_port)
 begin
 cyc_next = 1;
 stb_next = 1;
 we_next = 1;
 addr_next = tgt_addr;
 data_next = 1;
 sel_next = {bytesize{1'b1}};
 end
end

NP_functionality.VHDL_PROVIDED:
begin
process(in1)
variable temp_out1 : std_logic_vector(BITSIZE_out1-1 downto 0);
begin
 temp_out1 := (others => '0');
 for I in 0 to PORTSIZE_in1-1 loop
 temp_out1 := temp_out1 or in1(((I+1)*BITSIZE_in1)-1 downto (I*BITSIZE_in1));
 end loop; out1 <= temp_out1;
end process;

