-- synthesis translate_on
 mem(to_integer(unsigned(address_inw_mem))) := data_in_mem;
-- synthesis translate_off
 end if;
-- synthesis translate_on
 end if;
 end if;
-- synthesis translate_off
 if (to_integer(unsigned(address_inr_mem)) < n_elements) then
-- synthesis translate_on
 data_out_mem <= mem(to_integer(unsigned(address_inr_mem)));
