`define CTRL_ADDR_W 4
//Addresses for cache controller's task
`define ADDR_BUFFER_EMPTY (`CTRL_ADDR_W'd1)
`define ADDR_BUFFER_FULL (`CTRL_ADDR_W'd2) 
`define ADDR_CACHE_HIT (`CTRL_ADDR_W'd3) 
`define ADDR_CACHE_MISS (`CTRL_ADDR_W'd4) 
`define ADDR_CACHE_READ_ACCESS (`CTRL_ADDR_W'd5) 
`define ADDR_CACHE_READ_MISS (`CTRL_ADDR_W'd6) 
`define ADDR_CACHE_WRITE_ACCESS (`CTRL_ADDR_W'd7) 
`define ADDR_CACHE_WRITE_MISS (`CTRL_ADDR_W'd8) 
`define ADDR_RESET_COUNTER (`CTRL_ADDR_W'd9) 
`define ADDR_CACHE_INVALIDATE (`CTRL_ADDR_W'd10)

localparam FE_DATA_W = BITSIZE_rdata;

reg [BITSIZE_rdata - 1 : 0] rdata;
reg invalidate;
reg ready;

generate
if(CTRL_CNT)
begin : cnt

reg [FE_DATA_W-1:0] read_access_cnt, read_miss_cnt, write_access_cnt, write_miss_cnt;
wire [FE_DATA_W-1:0] hit_cnt, miss_cnt;
reg counter_reset;

assign hit_cnt = read_access_cnt + write_access_cnt;
assign miss_cnt = read_miss_cnt + write_miss_cnt;

always @ (posedge clock 1RESET_EDGE)
begin
if (1RESET_VALUE) 
begin
read_access_cnt <= {FE_DATA_W{1'b0}};
read_miss_cnt <= {FE_DATA_W{1'b0}};
write_access_cnt <= {FE_DATA_W{1'b0}};
write_miss_cnt <= {FE_DATA_W{1'b0}};
end
else
begin
if (counter_reset) 
begin
read_access_cnt <= {FE_DATA_W{1'b0}};
read_miss_cnt <= {FE_DATA_W{1'b0}};
write_access_cnt <= {FE_DATA_W{1'b0}};
write_miss_cnt <= {FE_DATA_W{1'b0}};
end
else
if (read_hit)
begin
read_access_cnt <= read_access_cnt + 1; 
end
else if (write_hit)
begin
write_access_cnt <= write_access_cnt + 1;
end
else if (read_miss)
begin
read_miss_cnt <= read_miss_cnt + 1;
end
else if (write_miss)
begin
write_miss_cnt <= write_miss_cnt + 1;
end
else
begin
read_access_cnt <= read_access_cnt;
read_miss_cnt <= read_miss_cnt;
write_access_cnt <= write_access_cnt;
write_miss_cnt <= write_miss_cnt;
end
end // else: !if(ctrl_arst) 
end // always @ (posedge clock, posedge ctrl_arst)

always @ (posedge clock)
begin
rdata <= {FE_DATA_W{1'b0}};
invalidate <= 1'b0;
counter_reset <= 1'b0;
ready <= valid; // Sends acknowlege the next clock cycle after request (handshake) 
if(valid)
if (addr == `ADDR_CACHE_HIT)
rdata <= hit_cnt;
else if (addr == `ADDR_CACHE_MISS)
rdata <= miss_cnt;
else if (addr == `ADDR_CACHE_READ_ACCESS)
rdata <= read_access_cnt;
else if (addr == `ADDR_CACHE_READ_MISS)
rdata <= read_miss_cnt;
else if (addr == `ADDR_CACHE_WRITE_ACCESS)
rdata <= write_access_cnt;
else if (addr == `ADDR_CACHE_WRITE_MISS)
rdata <= write_miss_cnt;
else if (addr == `ADDR_RESET_COUNTER)
counter_reset <= 1'b1;
else if (addr == `ADDR_CACHE_INVALIDATE)
invalidate <= 1'b1; 
else if (addr == `ADDR_BUFFER_EMPTY)
rdata <= wtbuf_empty;
else if (addr == `ADDR_BUFFER_FULL)
rdata <= wtbuf_full;
end // always @ (posedge clock)
end // if (CTRL_CNT)
else
begin

always @ (posedge clock)
begin
rdata <= {FE_DATA_W{1'b0}};
invalidate <= 1'b0;
ready <= valid; // Sends acknowlege the next clock cycle after request (handshake) 
if(valid)
if (addr == `ADDR_CACHE_INVALIDATE)
invalidate <= 1'b1; 
else if (addr == `ADDR_BUFFER_EMPTY)
rdata <= wtbuf_empty;
else if (addr == `ADDR_BUFFER_FULL)
rdata <= wtbuf_full; 
end // always @ (posedge clock)
end // else: !if(CTRL_CNT) 
endgenerate

//Write Policy
`define WRITE_THROUGH 0 //write-through not allocate: implements a write-through buffer
`define WRITE_BACK 1 //write-back allocate: implementes a dirty-memory

`define IOB_MAX(a,b) {((a) > (b)) ? (a) : (b)}
`define IOB_MIN(a,b) {((a) < (b)) ? (a) : (b)}


localparam FE_DATA_W = BITSIZE_rdata;
localparam BE_DATA_W = BITSIZE_read_rdata;
localparam NWAY_W = $clog2(N_WAYS);
localparam FE_NBYTES = FE_DATA_W/8;
localparam FE_BYTE_W = $clog2(FE_NBYTES);
localparam BE_NBYTES = BE_DATA_W/8;
localparam BE_BYTE_W = $clog2(BE_NBYTES);
localparam LINE2MEM_W = WORD_OFF_W-$clog2(BE_DATA_W/FE_DATA_W);
/* To avoid 0 size when using fully associative cache. Signals are ignored if the size should be 0 */
localparam INDEX_W = LINE_OFF_W > 0 ? LINE_OFF_W : 1;

localparam TAG_W = FE_ADDR_W - (FE_BYTE_W + WORD_OFF_W + LINE_OFF_W);
localparam BUF_DATA_SIZE = WRITE_POL == `WRITE_THROUGH ? FE_NBYTES+(FE_ADDR_W-FE_BYTE_W)+(FE_DATA_W) : FE_ADDR_W-FE_BYTE_W + (2**WORD_OFF_W)*FE_DATA_W;

wire hit;

//cache-memory internal signals
wire [N_WAYS-1:0] way_hit, way_select;

wire [TAG_W-1:0] tag = addr_reg[FE_ADDR_W-1 - (FE_BYTE_W) -:TAG_W]; //so the tag doesnt update during ready on a read-access, losing the current hit status (can take the 1 clock-cycle delay)
wire [INDEX_W-1:0] index;
wire [INDEX_W-1:0] index_reg;
wire [WORD_OFF_W-1:0] offset = addr_reg[FE_BYTE_W - (FE_BYTE_W) +:WORD_OFF_W]; //so the offset doesnt update during ready on a read-access (can take the 1 clock-cycle delay)

wire [N_WAYS*(2**WORD_OFF_W)*FE_DATA_W-1:0] line_rdata;
wire [N_WAYS*TAG_W-1:0] line_tag;
reg [N_WAYS*(2**LINE_OFF_W)-1:0] v_reg;
reg [N_WAYS-1:0] v;

reg [(2**WORD_OFF_W)*FE_NBYTES-1:0] line_wstrb;

wire write_access = |wstrb_reg & valid_reg;
wire read_access = ~|wstrb_reg & valid_reg; //signal mantains the access 1 addition clock-cycle after ready is asserted


//back-end write channel
wire buffer_empty, buffer_full;
wire [BUF_DATA_SIZE-1 : 0] buffer_dout;
wire [BUF_DATA_SIZE-1 : 0] buf_w_data;
wire buf_w_en;

//for write-back write-allocate only
reg [N_WAYS-1:0] dirty;
reg [N_WAYS*(2**LINE_OFF_W)-1:0] dirty_reg;


localparam S_IDLE = 2'b00, S_ADDR = 2'b01, S_WRITE = 2'b10;
reg [1:0] flush_state = S_IDLE, next_flush_state;
reg [(LINE_OFF_W + NWAY_W) - 1: 0] flush_addr, next_flush_addr;


generate
 if(LINE_OFF_W > 0) 
 begin
 assign index = addr [FE_ADDR_W-TAG_W-1 - (BE_BYTE_W + LINE2MEM_W) -:LINE_OFF_W];//cant wait, doesnt update during a write-access
 assign index_reg = addr_reg[FE_ADDR_W-TAG_W-1 - (FE_BYTE_W) -:INDEX_W];//cant wait, doesnt update during a write-access
 end
endgenerate

generate
 if(WRITE_POL == `WRITE_THROUGH) 
 begin

 localparam FIFO_DATA_W = FE_ADDR_W-FE_BYTE_W + FE_DATA_W + FE_NBYTES;
 localparam FIFO_ADDR_W = WTBUF_DEPTH_W;
 localparam MAXDATA_W = `IOB_MAX(FIFO_DATA_W, FIFO_DATA_W);
 localparam MINDATA_W = `IOB_MIN(FIFO_DATA_W, FIFO_DATA_W);
 localparam N = MAXDATA_W/MINDATA_W;
 localparam MINADDR_W = FIFO_ADDR_W-$clog2(N);
 wire mem_w_en;
 wire [FIFO_ADDR_W-1:0] mem_w_addr;
 wire [FIFO_DATA_W-1:0] mem_w_data;
 wire mem_r_en;
 wire [FIFO_ADDR_W-1:0] mem_r_addr;
 wire [FIFO_DATA_W-1:0] mem_r_data;

 // FIFO memory
 IOB_ram_2p #(.BITSIZE_w_addr(FIFO_ADDR_W),
 .BITSIZE_w_data(FIFO_DATA_W),
 .BITSIZE_r_addr(FIFO_ADDR_W),
 .BITSIZE_r_data(FIFO_DATA_W))
 iob_ram_2p0 (.clock(clock),
 .w_en(mem_w_en),
 .w_addr(mem_w_addr),
 .w_data(mem_w_data),
 .r_en(mem_r_en),
 .r_addr(mem_r_addr),
 .r_data(mem_r_data));

 IOB_fifo_sync #(.BITSIZE_ext_mem_w_en (N),
 .BITSIZE_ext_mem_w_data(MINDATA_W * N),
 .BITSIZE_ext_mem_w_addr(MINADDR_W * N),
 .BITSIZE_ext_mem_r_addr(MINADDR_W * N),
 .BITSIZE_ext_mem_r_data(MINDATA_W * N),
 .BITSIZE_r_data(FIFO_DATA_W),
 .BITSIZE_w_data(FIFO_DATA_W),
 .BITSIZE_level(FIFO_ADDR_W + 1))
 write_buffer (.clock(clock),
 .reset(reset),
 .ext_mem_w_en(mem_w_en),
 .ext_mem_w_addr(mem_w_addr),
 .ext_mem_w_data(mem_w_data),
 .ext_mem_r_en(mem_r_en),
 .ext_mem_r_addr(mem_r_addr),
 .ext_mem_r_data (mem_r_data),

 .level (),

 .r_data (buffer_dout),
 .r_empty (buffer_empty),
 .r_en (write_ready),
 .dirty (dirty_mem),

 .w_data (buf_w_data),
 .w_full (buffer_full),
 .w_en (buf_w_en),
 .write_done(write_done)
 );

 assign buf_w_data = {addr_reg,wdata_reg,wstrb_reg};
 assign buf_w_en = write_access & ready;

 //buffer status
 assign wtbuf_full = buffer_full;
 assign wtbuf_empty = buffer_empty & write_ready & ~write_valid;

 //back-end write channel
 assign write_valid = ~buffer_empty;
 assign write_addr = buffer_dout[FE_NBYTES + FE_DATA_W +: FE_ADDR_W - FE_BYTE_W];
 assign write_wdata = buffer_dout[FE_NBYTES +: FE_DATA_W ];
 assign write_wstrb = buffer_dout[0 +: FE_NBYTES ];


 //back-end read channel
 assign replace_valid = (~hit & read_access & ~replace) & (buffer_empty & write_ready);
 assign replace_addr = addr[FE_ADDR_W -1 - (BE_BYTE_W + LINE2MEM_W):BE_BYTE_W+LINE2MEM_W - (BE_BYTE_W + LINE2MEM_W)];

 end
 else begin // if (WRITE_POL == WRITE_BACK)
 localparam FIFO_ADDR_W = WTBUF_DEPTH_W;
 localparam FIFO_DATA_W = FE_ADDR_W-FE_BYTE_W + (2**WORD_OFF_W)*FE_DATA_W;

 wire mem_w_en;
 wire [FIFO_ADDR_W-1:0] mem_w_addr;
 wire [FIFO_DATA_W-1:0] mem_w_data;

 wire mem_r_en;
 wire [FIFO_ADDR_W-1:0] mem_r_addr;
 wire [FIFO_DATA_W-1:0] mem_r_data;
 wire buf_dirty;
 // FIFO memory
 IOB_ram_2p
 #(
 .BITSIZE_w_addr(FIFO_ADDR_W),
 .BITSIZE_w_data(FIFO_DATA_W),
 .BITSIZE_r_addr(FIFO_ADDR_W),
 .BITSIZE_r_data(FIFO_DATA_W)
 )
 iob_ram_2p0
 (
 .clock (clock),
 .w_en (mem_w_en),
 .w_addr (mem_w_addr),
 .w_data (mem_w_data),
 .r_en (mem_r_en),
 .r_addr (mem_r_addr),
 .r_data (mem_r_data)
 );
 IOB_fifo_sync 
 #(
 .BITSIZE_ext_mem_w_en (1),
 .BITSIZE_ext_mem_w_data(FIFO_DATA_W),
 .BITSIZE_ext_mem_w_addr(FIFO_ADDR_W),
 .BITSIZE_ext_mem_r_addr(FIFO_ADDR_W),
 .BITSIZE_ext_mem_r_data(FIFO_DATA_W),
 .BITSIZE_r_data (FIFO_DATA_W),
 .BITSIZE_w_data (FIFO_DATA_W),
 .BITSIZE_level (FIFO_ADDR_W + 1)
 )
 write_buffer
 (
 .clock (clock),
 .reset (reset),
 .ext_mem_w_en (mem_w_en),
 .ext_mem_w_addr (mem_w_addr),
 .ext_mem_w_data (mem_w_data),
 .ext_mem_r_en (mem_r_en),
 .ext_mem_r_addr (mem_r_addr),
 .ext_mem_r_data (mem_r_data),
 .level (),
 .r_data (buffer_dout),
 .r_empty (buffer_empty),
 .r_en (write_ready),
 .dirty (buf_dirty),
 .w_data (buf_w_data),
 .w_full (buffer_full),
 .w_en (buf_w_en),
 .write_done(write_done)
 );

 //buffer status
 assign write_valid = !buffer_empty;
 assign wtbuf_full = buffer_full;
 assign wtbuf_empty = buffer_empty & write_ready & ~write_valid;

 assign dirty_mem = |dirty_reg || buf_dirty;
 //back-end read channel
 assign replace_valid = (~|way_hit) & (write_ready) & valid_reg & ~replace;

 assign replace_addr = addr[FE_ADDR_W -1 - (BE_BYTE_W + LINE2MEM_W):BE_BYTE_W+LINE2MEM_W - (BE_BYTE_W + LINE2MEM_W)];

 //back-end write channel
 assign write_wstrb = {FE_NBYTES{1'bx}};
 assign write_addr = buffer_dout[FIFO_DATA_W - 1 -: (FE_ADDR_W - FE_BYTE_W)];
 assign write_wdata = buffer_dout[(2**WORD_OFF_W)*FE_DATA_W - 1 : 0]; 
 end
endgenerate


//////////////////////////////////////////////////////
// Read-After-Write (RAW) Hazard (pipeline) control
//////////////////////////////////////////////////////
wire raw;
reg write_hit_prev;
reg [WORD_OFF_W-1:0] offset_prev;
reg [N_WAYS-1:0] way_hit_prev;

generate
if (WRITE_POL == `WRITE_THROUGH) begin
 always @(posedge clock) begin
 write_hit_prev <= write_access & (|way_hit);
 //previous write position
 offset_prev <= offset;
 way_hit_prev <= way_hit;
 end
 assign raw = write_hit_prev & (way_hit_prev == way_hit) & (offset_prev == offset);
end
else begin //// if (WRITE_POL == WRITE_BACK)
 always @(posedge clock) begin
 write_hit_prev <= write_access; //all writes will have the data in cache in the end
 //previous write position
 offset_prev <= offset;
 way_hit_prev <= way_hit;
 end
 assign raw = write_hit_prev & (way_hit_prev == way_hit) & (offset_prev == offset) & read_access; //without read_access it is an infinite replacement loop
end
endgenerate


///////////////////////////////////////////////////////////////
// Hit signal: data available and in the memory's output
///////////////////////////////////////////////////////////////
assign hit = |way_hit & ~replace & (~raw);


/////////////////////////////////
//front-end READY signal
/////////////////////////////////
generate
 if (WRITE_POL == `WRITE_THROUGH)
 begin
 assign ready = (hit & read_access) | (~buffer_full & write_access);
 end
 else 
 begin
 assign ready = hit & valid_reg;
 end
endgenerate

//cache-control hit-miss counters enables
generate
 if(CTRL_CACHE & CTRL_CNT)
 begin
 //cache-control hit-miss counters enables
 assign write_hit = ready & ( hit & write_access);
 assign write_miss = replace_valid & write_access;
 assign read_hit = ready & ( hit & read_access);
 assign read_miss = replace_valid & read_access;
 end
 else
 begin
 assign write_hit = 1'bx;
 assign write_miss = 1'bx;
 assign read_hit = 1'bx;
 assign read_miss = 1'bx;
 end // else: !if(CACHE_CTRL & CTRL_CNT)
endgenerate


////////////////////////////////////////
//Memories implementation configurations
////////////////////////////////////////
genvar i,j,k;
generate

 if(LINE_OFF_W > 0 && WRITE_POL == `WRITE_BACK) 
 begin
 //Data-Memory
 for (k = 0; k < N_WAYS; k=k+1) 
 begin : n_ways_block
 for(j = 0; j < 2**LINE2MEM_W; j=j+1) 
 begin : line2mem_block
 for(i = 0; i < BE_DATA_W/FE_DATA_W; i=i+1) 
 begin : BE_FE_block_LINE_OFF_W_GT_0_WRITE_BACK
 IOB_gen_sp_ram #(.BITSIZE_we(FE_DATA_W / 8),
 .BITSIZE_addr(LINE_OFF_W),
 .BITSIZE_data_out(FE_DATA_W),
 .BITSIZE_data_in(FE_DATA_W)) 
 cache_memory_ram (.clock(clock),
 .en(valid || flush),
 .we({FE_NBYTES{way_hit[k]}} & line_wstrb[(j*(BE_DATA_W/FE_DATA_W)+i)*FE_NBYTES +: FE_NBYTES]),
 .addr(flush ? flush_addr[LINE_OFF_W - 1 : 0] : (write_access & way_hit[k] & ((j*(BE_DATA_W/FE_DATA_W)+i) == offset))? index_reg : index),
 .data_in((replace)? read_rdata[i*FE_DATA_W +: FE_DATA_W] : wdata_reg),
 .data_out(line_rdata[(k*(2**WORD_OFF_W)+j*(BE_DATA_W/FE_DATA_W)+i)*FE_DATA_W +: FE_DATA_W]));
 end
 end
 end
 end
 else if (LINE_OFF_W > 0)
 begin
 //Data-Memory
 for (k = 0; k < N_WAYS; k=k+1) 
 begin : n_ways_block
 for(j = 0; j < 2**LINE2MEM_W; j=j+1) 
 begin : line2mem_block
 for(i = 0; i < BE_DATA_W/FE_DATA_W; i=i+1) 
 begin : BE_FE_block_LINE_OFF_W_GT_0
 IOB_gen_sp_ram #(.BITSIZE_we(FE_DATA_W / 8),
 .BITSIZE_addr(LINE_OFF_W),
 .BITSIZE_data_out(FE_DATA_W),
 .BITSIZE_data_in(FE_DATA_W)) 
 cache_memory (.clock(clock),
 .en(valid),
 .we({FE_NBYTES{way_hit[k]}} & line_wstrb[(j*(BE_DATA_W/FE_DATA_W)+i)*FE_NBYTES +: FE_NBYTES]),
 .addr((write_access & way_hit[k] & ((j*(BE_DATA_W/FE_DATA_W)+i) == offset))? index_reg : index),
 .data_in((replace)? read_rdata[i*FE_DATA_W +: FE_DATA_W] : wdata_reg),
 .data_out(line_rdata[(k*(2**WORD_OFF_W)+j*(BE_DATA_W/FE_DATA_W)+i)*FE_DATA_W +: FE_DATA_W]));
 end
 end
 end
 end
 else if(WRITE_POL == `WRITE_BACK)
 begin
 //Data-Memory
 for (k = 0; k < N_WAYS; k=k+1) 
 begin : n_ways_block
 for(j = 0; j < 2**LINE2MEM_W; j=j+1) 
 begin : line2mem_block
 for(i = 0; i < BE_DATA_W/FE_DATA_W; i=i+1) 
 begin : BE_FE_block_WRITE_BACK
 IOB_gen_sp_ram_no_addr #(.BITSIZE_we(FE_DATA_W / 8),
 .BITSIZE_data_out(FE_DATA_W),
 .BITSIZE_data_in(FE_DATA_W)) 
 cache_memory (
 .clock(clock),
 .en(valid || flush),
 .we({FE_NBYTES{way_hit[k]}} & line_wstrb[(j*(BE_DATA_W/FE_DATA_W)+i)*FE_NBYTES +: FE_NBYTES]),
 .data_in ((replace)? read_rdata[i*FE_DATA_W +: FE_DATA_W] : wdata_reg),
 .data_out(line_rdata[(k*(2**WORD_OFF_W)+j*(BE_DATA_W/FE_DATA_W)+i)*FE_DATA_W +: FE_DATA_W]));
 end
 end
 end
 end
 else
 begin
 //Data-Memory
 for (k = 0; k < N_WAYS; k=k+1) 
 begin : n_ways_block
 for(j = 0; j < 2**LINE2MEM_W; j=j+1) 
 begin : line2mem_block
 for(i = 0; i < BE_DATA_W/FE_DATA_W; i=i+1) 
 begin : BE_FE_block_ELSE
 IOB_gen_sp_ram_no_addr #(.BITSIZE_we(FE_DATA_W / 8),
 .BITSIZE_data_out(FE_DATA_W),
 .BITSIZE_data_in(FE_DATA_W)) 
 cache_memory (
 .clock(clock),
 .en(valid),
 .we({FE_NBYTES{way_hit[k]}} & line_wstrb[(j*(BE_DATA_W/FE_DATA_W)+i)*FE_NBYTES +: FE_NBYTES]),
 .data_in ((replace)? read_rdata[i*FE_DATA_W +: FE_DATA_W] : wdata_reg),
 .data_out(line_rdata[(k*(2**WORD_OFF_W)+j*(BE_DATA_W/FE_DATA_W)+i)*FE_DATA_W +: FE_DATA_W]));
 end
 end
 end
 end

 //Cache Line Write Strobe
 if(LINE2MEM_W > 0)
 begin
 always @(*)
 if(replace)
 line_wstrb = {BE_NBYTES{read_valid}} << (read_addr*BE_NBYTES); //line-replacement: read_addr indexes the words in cache-line
 else
 line_wstrb = (wstrb_reg & {FE_NBYTES{write_access}}) << (offset*FE_NBYTES);
 end
 else
 begin
 always @(*)
 if(replace)
 line_wstrb = {BE_NBYTES{read_valid}}; //line-replacement: mem's word replaces entire line
 else
 line_wstrb = (wstrb_reg & {FE_NBYTES{write_access}}) << (offset*FE_NBYTES);
 end // else: !if(LINE2MEM_W < 0)


 // Valid-Tag memories & replacement-policy
 if(N_WAYS > 1)
 begin

 wire [NWAY_W-1:0] way_hit_bin, way_select_bin;//reason for the 2 generates for single vs multiple ways

 if(LINE_OFF_W > 0) begin
 //valid-memory
 always @ (posedge clock 1RESET_EDGE) 
 begin
 if (1RESET_VALUE)
 v_reg <= 0;
 else if (invalidate)
 v_reg <= 0;
 else if(replace_valid)
 v_reg <= v_reg | (1<<(way_select_bin*(2**LINE_OFF_W) + index_reg));
 else
 v_reg <= v_reg;
 end

 for(k = 0; k < N_WAYS; k = k+1) 
 begin : tag_mem_block
 //valid-memory output stage register - 1 c.c. read-latency (cleaner simulation during rep.)
 always @(posedge clock)
 begin
 if(invalidate)
 begin
 v[k] <= 0;
 end
 else
 begin
 v[k] <= v_reg [(2**LINE_OFF_W)*k + index];
 end
 end

 if(WRITE_POL == `WRITE_BACK)
 begin
 //tag-memory
 IOB_ram_sp #(.BITSIZE_addr(LINE_OFF_W),
 .BITSIZE_dout(TAG_W),
 .BITSIZE_din(TAG_W))
 tag_memory (.clock(clock),
 .en(valid || flush_state == S_ADDR),
 .we (way_select[k] & replace_valid),
 .addr(flush_state == S_ADDR ? flush_addr[LINE_OFF_W - 1 : 0] : index),
 .din (tag),
 .dout(line_tag[TAG_W*k +: TAG_W])); 

 //Way hit signal - hit or replacement
 assign way_hit[k] = flush ? (flush_addr[LINE_OFF_W +: NWAY_W] == k) : (tag == line_tag[TAG_W*k +: TAG_W]) & v[k];
 end
 else
 begin
 //tag-memory
 IOB_ram_sp #(.BITSIZE_addr(LINE_OFF_W),
 .BITSIZE_dout(TAG_W),
 .BITSIZE_din(TAG_W))
 tag_memory (.clock(clock),
 .en(valid),
 .we (way_select[k] & replace_valid),
 .addr(index),
 .din (tag),
 .dout(line_tag[TAG_W*k +: TAG_W])); 

 //Way hit signal - hit or replacement
 assign way_hit[k] = (tag == line_tag[TAG_W*k +: TAG_W]) & v[k];
 end
 end
 end 
 else 
 begin
 //valid-memory
 always @ (posedge clock 1RESET_EDGE) 
 begin
 if (1RESET_VALUE)
 v_reg <= 0;
 else if (invalidate)
 v_reg <= 0;
 else if(replace_valid)
 v_reg <= v_reg | (1<<way_select_bin);
 else
 v_reg <= v_reg;
 end

 for(k = 0; k < N_WAYS; k = k+1) begin : tag_mem_block
 //valid-memory output stage register - 1 c.c. read-latency (cleaner simulation during rep.)
 always @(posedge clock)
 if(invalidate)
 v[k] <= 0;
 else
 v[k] <= v_reg [k];

 if(WRITE_POL == `WRITE_BACK)
 begin
 //tag-memory
 IOB_ram_sp_no_addr #(.BITSIZE_dout(TAG_W),
 .BITSIZE_din(TAG_W))
 tag_memory (.clock(clock),
 .en(valid|| flush_state == S_ADDR),
 .we(way_select[k] & replace_valid),
 .din (tag),
 .dout(line_tag[TAG_W*k +: TAG_W]));
 end
 else
 begin
 //tag-memory
 IOB_ram_sp_no_addr #(.BITSIZE_dout(TAG_W),
 .BITSIZE_din(TAG_W))
 tag_memory (.clock(clock),
 .en(valid),
 .we(way_select[k] & replace_valid),
 .din (tag),
 .dout(line_tag[TAG_W*k +: TAG_W]));
 end

 if(WRITE_POL == `WRITE_BACK)
 begin
 //Way hit signal - hit or replacement
 assign way_hit[k] = flush ? (flush_addr[LINE_OFF_W +: NWAY_W] == k) : (tag == line_tag[TAG_W*k +: TAG_W]) & v[k];
 end
 else
 begin
 //Way hit signal - hit or replacement
 assign way_hit[k] = (tag == line_tag[TAG_W*k +: TAG_W]) & v[k];
 end
 end
 end


 //Read Data Multiplexer
 assign rdata [FE_DATA_W-1:0] = line_rdata >> FE_DATA_W*(offset + (2**WORD_OFF_W)*way_hit_bin);


 //replacement-policy module
 IOB_replacement_policy #(
 .BITSIZE_way_hit(N_WAYS),
 .BITSIZE_line_addr(LINE_OFF_W),
 .BITSIZE_way_select(N_WAYS),
 .BITSIZE_way_select_bin(NWAY_W),
 .REP_POLICY(REP_POLICY)
 )
 replacement_policy_algorithm
 (
 .clock (clock ),
 .reset (1RESET_VALUE|invalidate),
 .write_en (ready ),
 .way_hit (way_hit ),
 .line_addr (index_reg ),
 .way_select(way_select ),
 .way_select_bin(way_select_bin)
 );

 //onehot-to-binary for way-hit
 IOB_onehot_to_bin #(
 .BITSIZE_onehot(2**NWAY_W - 1),
 .BITSIZE_bin(NWAY_W)
 )
 way_hit_encoder
 (
 .onehot(way_hit[N_WAYS-1:1]),
 .bin (way_hit_bin)
 );

 //dirty-memory
 if(WRITE_POL == `WRITE_BACK)
 begin
 if(LINE_OFF_W > 0) 
 begin
 always @ (posedge clock 1RESET_EDGE) 
 begin
 if (1RESET_VALUE)
 begin
 dirty_reg <= 0;
 end
 else if (flush_state == S_WRITE && !buffer_full) 
 begin
 dirty_reg <= dirty_reg & ~(1<<flush_addr);
 end 
 else if(write_access & hit)
 begin
 dirty_reg <= dirty_reg | (1<<(way_hit_bin*(2**LINE_OFF_W) + index_reg));//updates position with 1
 end
 else
 begin
 dirty_reg <= dirty_reg;
 end
 end

 for(k = 0; k < N_WAYS; k = k+1) 
 begin : dirty_block
 //valid-memory output stage register - 1 c.c. read-latency (cleaner simulation during rep.)
 always @(posedge clock)
 begin
 dirty[k] <= dirty_reg [(2**LINE_OFF_W)*k + index];
 end
 end
 end 
 else 
 begin
 always @ (posedge clock 1RESET_EDGE) 
 begin
 if (1RESET_VALUE)
 begin
 dirty_reg <= 0;
 end
 else if (flush_state == S_WRITE && !buffer_full) 
 begin
 dirty_reg <= dirty_reg & ~(1<<flush_addr);
 end 
 else if(write_access & hit)
 begin
 dirty_reg <= dirty_reg | (1<<(way_hit_bin*(2**LINE_OFF_W)));//updates position with 1
 end
 else
 begin
 dirty_reg <= dirty_reg;
 end
 end

 for(k = 0; k < N_WAYS; k = k+1) 
 begin : dirty_block
 //valid-memory output stage register - 1 c.c. read-latency (cleaner simulation during rep.)
 always @(posedge clock)
 dirty[k] <= dirty_reg [k];
 end
 end

 //flush line
 wire [TAG_W-1:0] tag_flush = line_tag >> ((flush? way_hit_bin : way_select_bin)*TAG_W); //auxiliary wire
 assign buf_w_en = (valid_reg && (way_hit == 'b0) && (way_select & dirty) && replace_valid) || flush_state == S_WRITE;
 wire [FE_DATA_W*(2**WORD_OFF_W) - 1 : 0] data_flush = line_rdata >> ((flush ? way_hit_bin : way_select_bin) *FE_DATA_W*(2**WORD_OFF_W));
 if(LINE_OFF_W > 0) begin
 assign buf_w_data = {{tag_flush, flush ? flush_addr[LINE_OFF_W - 1 : 0] : index_reg}, data_flush}; 
 end else begin
 assign buf_w_data = {tag_flush, data_flush}; 
 end
 end // if (WRITE_POL == WRITE_BACK)
 end
 else // (N_WAYS = 1)
 begin
 //valid-memory
 always @ (posedge clock 1RESET_EDGE)
 begin
 if (1RESET_VALUE)
 v_reg <= 0;
 else if (invalidate)
 v_reg <= 0;
 else if(replace_valid)
 v_reg <= v_reg | (1 << index);
 else
 v_reg <= v_reg;
 end

 //valid-memory output stage register - 1 c.c. read-latency (cleaner simulation during rep.)
 always @(posedge clock)
 if(invalidate)
 v <= 0;
 else
 v <= v_reg [index];

 if(WRITE_POL == `WRITE_BACK)
 begin
 //tag-memory
 IOB_ram_sp #(.BITSIZE_addr(LINE_OFF_W),
 .BITSIZE_dout(TAG_W),
 .BITSIZE_din(TAG_W))
 tag_memory (.clock (clock),
 .en(valid || flush_state == S_ADDR),
 .we(replace_valid),
 .addr(flush_state == S_ADDR ? flush_addr[LINE_OFF_W - 1 : 0] : index),
 .din(tag),
 .dout(line_tag));
 end
 else
 begin
 //tag-memory
 IOB_ram_sp #(.BITSIZE_addr(LINE_OFF_W),
 .BITSIZE_dout(TAG_W),
 .BITSIZE_din(TAG_W))
 tag_memory (.clock (clock),
 .en(valid),
 .we(replace_valid),
 .addr(index),
 .din(tag),
 .dout(line_tag));
 end


 //Cache hit signal that indicates which way has had the hit (also during replacement)
 assign way_hit = (tag == line_tag) & v;

 //Read Data Multiplexer
 assign rdata [FE_DATA_W-1:0] = line_rdata >> FE_DATA_W*offset;

 //dirty-memory
 if(WRITE_POL == `WRITE_BACK)
 begin
 //dirty-memory
 always @ (posedge clock 1RESET_EDGE) begin
 if (1RESET_VALUE)
 dirty_reg <= 0;
 else if(flush_state == S_WRITE && !buffer_full) begin
 dirty_reg <= dirty_reg & ~(1 << flush_addr);
 end else if(!flush) begin
 if(write_access & hit)
 dirty_reg <= dirty_reg | (1<<(index_reg)); //updates position with 1 (needs to be index_reg otherwise updates the new index if the previous access was a write)
 end else
 dirty_reg <= dirty_reg;
 end

 always @(posedge clock)
 begin
 dirty <= dirty_reg [index];
 end

 assign buf_w_en = ((write_access || read_access) && (~(way_hit) & dirty) && replace_valid) || flush_state == S_WRITE;
 assign buf_w_data = {{line_tag, flush_state == S_WRITE ? flush_addr[LINE_OFF_W - 1 : 0] : index_reg}, line_rdata};
 end 
 end // else: !if(N_WAYS > 1)
endgenerate

generate
 if(WRITE_POL == `WRITE_BACK) 
 begin

 always @(*) 
 begin
 next_flush_state = flush_state;
 next_flush_addr = 0;
 case(flush_state)
 S_IDLE: 
 begin
 if(flush) 
 begin
 next_flush_state = S_ADDR;
 end
 end
 S_ADDR: begin
 if(dirty_reg[flush_addr]) 
 begin
 next_flush_addr = flush_addr;
 next_flush_state = S_WRITE;
 end 
 else if (|dirty_reg) 
 begin
 next_flush_addr = flush_addr + 1;
 next_flush_state = S_ADDR;
 end 
 else 
 begin
 next_flush_state = S_IDLE;
 end
 end
 S_WRITE: 
 begin
 if(!buffer_full) 
 begin
 next_flush_addr = flush_addr + 1;
 next_flush_state = S_ADDR;
 end 
 else 
 begin
 next_flush_addr = flush_addr;
 next_flush_state = S_WRITE;
 end
 end
 default: 
 begin
 next_flush_state = S_IDLE;
 end
 endcase
 end

 always @(posedge clock) 
 begin
 if(1RESET_VALUE) 
 begin
 flush_state <= S_IDLE;
 flush_addr <= 0;
 end
 else
 begin
 flush_state <= next_flush_state;
 flush_addr <= next_flush_addr;
 end 
 end 
 end
endgenerate

