addr_reg = addr;
end
end

always @(posedge clock) begin
done_input_reg <= done_input_next;
if((Min_oe_ram || Min_we_ram) && !data_valid_reg) begin
acc_ctxt <= Min_accelerator_context_in;
end
if(done_input_next) begin
done <= !dirty;
end
Min_back_pressure <= data_valid_reg && (Min_we_ram || Min_oe_ram) ? Min_back_pressure_progress : 1'b0;
Min_back_pressure_progress <= data_valid_reg && !Min_datardy ? 1'b1 : 1'b0;
end

assign Min_accelerator_context = acc_ctxt;

