//.wdata (data_wdata),
// .wstrb (data_wstrb),
.rdata (data_rdata),
.ready (data_ready),
.dirty_mem (dirty),
//stored data signals
.valid_reg (data_valid_reg), 
.addr_reg (data_addr_reg),
.wdata_reg (data_wdata_reg),
.wstrb_reg (data_wstrb_reg),
//back-end
//write-through-buffer (write-channel)
.write_valid (write_valid),
.write_addr (write_addr),
.write_wdata (write_wdata),
.write_wstrb (write_wstrb),
.write_ready (write_ready),
.write_done (write_done),
//cache-line replacement (read-channel)
.replace_valid (replace_valid),
.replace_addr (replace_addr),
.replace (replace),
.read_valid (read_valid),
.read_addr (read_addr),
.read_rdata (read_rdata),
//control's signals
.wtbuf_empty (wtbuf_empty),
.wtbuf_full (wtbuf_full),
.write_hit (write_hit),
.write_miss (write_miss),
.read_hit (read_hit),
.read_miss (read_miss),
.flush(done_input)
);

IOB_back_end_minimal
#(
.FE_ADDR_W(FE_ADDR_W),
.FE_DATA_W(FE_DATA_W),
.WORD_OFF_W(WORD_OFF_W),
.BE_ADDR_W(BE_ADDR_W),
.BITSIZE_write_addr(FE_ADDR_W - (FE_BYTE_W + WRITE_POL * WORD_OFF_W)),
.BITSIZE_write_wdata(FE_DATA_W + WRITE_POL*(FE_DATA_W*(2**WORD_OFF_W)-FE_DATA_W)),
.BITSIZE_write_wstrb(FE_NBYTES),
.BITSIZE_replace_addr(FE_ADDR_W - (FE_BYTE_W + WORD_OFF_W)),
.BITSIZE_read_addr(LINE2MEM_W),
.BITSIZE_read_rdata(BE_DATA_W),
.BITSIZE_acc_ctxt(BITSIZE_Min_accelerator_context_in),
.BITSIZE_Mout_addr_ram(BE_ADDR_W),
.BITSIZE_Mout_Wdata_ram(BE_DATA_W),
.BITSIZE_Mout_data_ram_size(BITSIZE_Min_data_size_ram),
.BITSIZE_Mout_accelerator_context(BITSIZE_Mout_accelerator_context),
.BITSIZE_M_Rdata_ram(BE_DATA_W),
.BITSIZE_M_accelerator_context(BITSIZE_M_accelerator_context)
) 
back_end (
.clock(clock),
.reset(reset),
.write_valid (write_valid),
.write_addr (write_addr),
.write_wdata (write_wdata),
.write_wstrb (write_wstrb),
.write_ready (write_ready),
.write_done (write_done),
.replace_valid (replace_valid),
.replace_addr (replace_addr),
.replace (replace),
.read_valid (read_valid),
.read_addr (read_addr),
.read_rdata (read_rdata),
.acc_ctxt (acc_ctxt),
.back_pressure(Min_back_pressure_in),
.Mout_oe_ram(Mout_oe_ram),
.Mout_we_ram(Mout_we_ram),
.Mout_addr_ram(Mout_addr_ram),
.Mout_Wdata_ram(Mout_Wdata_ram),
.Mout_data_ram_size(Mout_data_ram_size),
.Mout_accelerator_context(Mout_accelerator_context),
.Mout_back_pressure(Mout_back_pressure),
.M_data_ready(M_DataRdy),
.M_Rdata_ram(M_Rdata_ram),
.M_accelerator_context(M_accelerator_context),
.M_back_pressure(M_back_pressure)
);


generate
if (CTRL_CACHE)
IOB_cache_control
#(
.CTRL_CNT (CTRL_CNT),
.BITSIZE_rdata(CTRL_CNT * FE_DATA_W)
)
cache_control
(
.clock (clock),
.reset (reset),
//control's signals
.valid (ctrl_valid),
.addr (ctrl_addr),
//write data
.wtbuf_full (wtbuf_full),
.wtbuf_empty (wtbuf_empty), 
.write_hit (write_hit),
.write_miss (write_miss),
.read_hit (read_hit),
.read_miss (read_miss),
////////////
.rdata (ctrl_rdata),
.ready (ctrl_ready),
.invalidate (invalidate)
);
else
begin
assign ctrl_rdata = 1'bx;
assign ctrl_ready = 1'bx;
assign invalidate = 1'b0;
end // else: !if(CTRL_CACHE)

endgenerate
`undef CTRL_ADDR_W
`undef WORD_ADDR

//COMMON UTILS
`define IOB_MAX(a,b) {((a) > (b)) ? (a) : (b)}
`define IOB_MIN(a,b) {((a) < (b)) ? (a) : (b)}

//IOB_REGISTER
`define IOB_REG_AR(CLK, RST_VAL, OUT, IN) always @(posedge CLK 1RESET_EDGE) if (1RESET_VALUE) OUT <= RST_VAL; else OUT <= IN;
`define IOB_REG_ARE(CLK, RST_VAL, EN, OUT, IN) always @(posedge CLK 1RESET_EDGE) if (1RESET_VALUE) OUT <= RST_VAL; \n else if (EN) OUT <= IN;


//IOB_COUNTER
`define IOB_COUNTER_ARE(CLK, EN, NAME) \n `IOB_REG_ARE(CLK, 1'b0, EN, NAME, NAME+1'b1)
localparam W_DATA_W = BITSIZE_w_data;
localparam R_DATA_W = BITSIZE_r_data;
localparam ADDR_W = BITSIZE_level - 1;
localparam MAXDATA_W = `IOB_MAX(W_DATA_W, R_DATA_W);
localparam MINDATA_W = `IOB_MIN(W_DATA_W, R_DATA_W);
localparam N = MAXDATA_W/MINDATA_W;
localparam MINADDR_W = ADDR_W-$clog2(N);//lower ADDR_W (higher DATA_W)
localparam W_ADDR_W = (W_DATA_W == MAXDATA_W) ? MINADDR_W : ADDR_W;
localparam R_ADDR_W = (R_DATA_W == MAXDATA_W) ? MINADDR_W : ADDR_W;

localparam ADDR_W_DIFF = $clog2(N);
localparam [ADDR_W:0] FIFO_SIZE = (1 << ADDR_W); //in bytes

reg [BITSIZE_level - 1 : 0] level;
reg r_empty;
reg w_full;
reg w_full_nxt = 0;

//effective write enable
wire w_en_int = (w_en & ~w_full);

//write address
reg [W_ADDR_W-1:0] w_addr;
`IOB_COUNTER_ARE(clock, w_en_int, w_addr)

//effective read enable
wire r_en_int = (r_en & ~r_empty);

//backup address (to read in case of write fail)
reg [R_ADDR_W-1:0] b_addr;
`IOB_COUNTER_ARE(clock, write_done, b_addr)

//read address
reg [R_ADDR_W-1:0] r_addr;
`IOB_COUNTER_ARE(clock, r_en_int, r_addr)

assign dirty = w_full || r_addr != b_addr; 

//assign according to assymetry type
localparam [ADDR_W:0] w_incr = (W_DATA_W > R_DATA_W) ? 1 << ADDR_W_DIFF : 1;
localparam [ADDR_W:0] r_incr = (R_DATA_W > W_DATA_W) ? 1 << ADDR_W_DIFF : 1;

//FIFO level
reg [ADDR_W+1:0] level_nxt;
`IOB_REG_AR(clock, 1'b0, level, level_nxt[0+:ADDR_W+1])

reg [W_ADDR_W - 1:0] w_addr_next;

always @(*) 
begin
 level_nxt = {1'd0,level};
 if(r_en_int && w_en_int)
 begin
 level_nxt = (level + w_incr) - r_incr;
 end
 else if(w_en_int)
 begin
 level_nxt = level + w_incr;
 end
 else if (r_en_int) // (!w_en_int) && r_en_int
 begin
 level_nxt = level -r_incr;
 end
end

always @(*) 
begin
 w_addr_next = w_addr;
 w_full_nxt = w_full;
 if(w_en_int && write_done)
 begin
 w_full_nxt = w_addr == b_addr;
 end
 else if(write_done)
 begin
 w_full_nxt = 1'b0;
 end
 else if(w_en_int) 
 begin
 w_addr_next = (w_addr + 1);
 w_full_nxt = w_addr_next == b_addr;
 end
end

//FIFO empty
wire r_empty_nxt;
assign r_empty_nxt = (level_nxt[0+:ADDR_W+1] < r_incr);
`IOB_REG_AR(clock, 1'd1, r_empty, r_empty_nxt)

//FIFO full
`IOB_REG_AR(clock, 1'd0, w_full, w_full_nxt)

//FIFO memory
IOB_ram_2p_asym #(.W_DATA_W (W_DATA_W),
 .R_DATA_W (R_DATA_W),
 .ADDR_W (ADDR_W),
 .BITSIZE_ext_mem_w_en(BITSIZE_ext_mem_w_en),
 .BITSIZE_ext_mem_w_data(BITSIZE_ext_mem_w_data),
 .BITSIZE_ext_mem_w_addr(BITSIZE_ext_mem_w_addr),
 .BITSIZE_ext_mem_r_addr(BITSIZE_ext_mem_r_addr),
 .BITSIZE_ext_mem_r_data(BITSIZE_ext_mem_r_data),
 .BITSIZE_w_data(BITSIZE_w_data),
 .BITSIZE_w_addr(W_ADDR_W),
 .BITSIZE_r_addr(R_ADDR_W),
 .BITSIZE_r_data(BITSIZE_r_data))
iob_ram_2p_asym0 (.clock(clock), 
 .ext_mem_w_en (ext_mem_w_en),
 .ext_mem_w_data(ext_mem_w_data),
 .ext_mem_w_addr(ext_mem_w_addr),
 .ext_mem_r_en (ext_mem_r_en),
 .ext_mem_r_addr(ext_mem_r_addr),
 .ext_mem_r_data(ext_mem_r_data),
 .w_en(w_en_int),
 .w_data(w_data),
 .w_addr(w_addr),
 .r_en(r_en_int),
 .r_addr(r_addr),
 .r_data(r_data));
`undef IOB_MAX
`undef IOB_MIN
`undef IOB_REG_AR
`undef IOB_REG_ARE
`undef IOB_COUNTER_ARE

`define CTRL_ADDR_W 4
localparam FE_DATA_W = BITSIZE_wdata;
localparam FE_NBYTES = BITSIZE_wstrb;
localparam FE_BYTE_W = $clog2(FE_NBYTES);
wire valid_int;

reg valid_reg;
reg valid_reg_next;
reg [FE_ADDR_W-1:FE_BYTE_W] addr_reg;
reg [FE_ADDR_W-1:FE_BYTE_W] addr_reg_next;
reg [FE_DATA_W-1:0] wdata_reg;
reg [FE_DATA_W-1:0] wdata_reg_next;
reg [FE_NBYTES-1:0] wstrb_reg;
reg [FE_NBYTES-1:0] wstrb_reg_next;

//////////////////////////////////////////////////////////////////////////////////
 // Cache-selection - cache-memory or cache-control 
/////////////////////////////////////////////////////////////////////////////////
generate
 if(CTRL_CACHE) 
 begin
 //Front-end output signals
 assign ready = ctrl_ready | data_ready;
 assign rdata = (ctrl_ready)? ctrl_rdata : data_rdata;
 assign valid_int = ~addr[CTRL_CACHE + FE_ADDR_W -1 - FE_BYTE_W] & valid;
 assign ctrl_valid = addr[CTRL_CACHE + FE_ADDR_W -1 - FE_BYTE_W] & valid; 
 assign ctrl_addr = addr[FE_BYTE_W - FE_BYTE_W +: `CTRL_ADDR_W]; 
 end
 else 
 begin
 //Front-end output signals
 assign ready = data_ready; 
 assign rdata = data_rdata; 
 assign valid_int = valid; 
 assign ctrl_valid = 1'bx;
 assign ctrl_addr = `CTRL_ADDR_W'dx; 
 end
endgenerate

//////////////////////////////////////////////////////////////////////////////////
// Input Data stored signals
/////////////////////////////////////////////////////////////////////////////////

always @(posedge clock 1RESET_EDGE)
begin
 if(1RESET_VALUE)
 begin
 valid_reg <= 0;
 addr_reg <= 0;
 wdata_reg <= 0;
 wstrb_reg <= 0; 
 end
 else 
 begin
 valid_reg <= valid_reg_next;
 addr_reg <= addr_reg_next;
 wdata_reg <= wdata_reg_next;
 wstrb_reg <= wstrb_reg_next; 
 end
end

always @(*)
begin
 if(ready) 
 begin
 valid_reg_next = 0;
 addr_reg_next = 0;
 wdata_reg_next = 0;
 wstrb_reg_next = 0;
 end
 else if(valid)
 begin
 valid_reg_next = valid_int;
 addr_reg_next = addr[FE_ADDR_W-1 - FE_BYTE_W : 0];
 wdata_reg_next = wdata;
 wstrb_reg_next = wstrb;
 end
 else
 begin
 valid_reg_next = valid_reg;
 addr_reg_next = addr_reg;
 wdata_reg_next = wdata_reg;
 wstrb_reg_next = wstrb_reg;
 end
end


//////////////////////////////////////////////////////////////////////////////////
// Data-output ports
/////////////////////////////////////////////////////////////////////////////////

assign data_addr = addr[FE_ADDR_W-1 - FE_BYTE_W : 0];
assign data_valid = valid_int | valid_reg;
assign data_addr_reg = addr_reg[FE_ADDR_W-1 : FE_BYTE_W];
assign data_wdata_reg = wdata_reg;
assign data_wstrb_reg = wstrb_reg;
assign data_valid_reg = valid_reg;

localparam BIN_W = BITSIZE_bin;

reg [BITSIZE_bin - 1 : 0] bin;

always @ (*) 
begin: onehot_to_binary_encoder
 integer i;
 reg [BIN_W-1:0] bin_cnt ;
 bin_cnt = 0;
 for (i=1; i<2**BIN_W; i=i+1)
 begin
 if (onehot[i - 1])
 begin
 bin_cnt = bin_cnt|i;
 end
 end
 bin = bin_cnt; 
end

reg [BITSIZE_r_data - 1 : 0] r_data;
localparam DATA_W = BITSIZE_w_data;
localparam ADDR_W = BITSIZE_w_addr;

// Declare the RAM
reg [DATA_W-1:0] mem [(2**ADDR_W)-1:0];

integer index;
// Initialize the RAM
initial
begin
 for(index=0; index<(2**ADDR_W); index=index+1)
 begin
 mem[index] = 0;
 end
end

//read port
always @(posedge clock)
begin
 if(r_en)
 begin
 r_data <= mem[r_addr];
 end
end

//write port
always @(posedge clock)
begin
 if(w_en)
 begin
 mem[w_addr] <= w_data;
 end
end

`define IOB_MAX(a,b) {((a) > (b)) ? (a) : (b)}
`define IOB_MIN(a,b) {((a) < (b)) ? (a) : (b)}

reg [BITSIZE_r_data - 1 : 0] r_data;

localparam MAXDATA_W = `IOB_MAX(W_DATA_W, R_DATA_W);
localparam MINDATA_W = `IOB_MIN(W_DATA_W, R_DATA_W);
localparam MINADDR_W = ADDR_W-$clog2(MAXDATA_W/MINDATA_W);//lower ADDR_W (higher DATA_W)
localparam W_ADDR_W = (W_DATA_W == MAXDATA_W) ? MINADDR_W : ADDR_W;
localparam R_ADDR_W = (R_DATA_W == MAXDATA_W) ? MINADDR_W : ADDR_W;
//determine the number of blocks N
localparam N = MAXDATA_W/MINDATA_W;

//symmetric memory block buses
//write buses
reg [N-1:0] en_wr;
reg [MINDATA_W-1:0] data_wr [N-1:0];
reg [MINADDR_W-1:0] addr_wr [N-1:0];

//read buses
wire [MINDATA_W-1:0] data_rd [N-1:0];
reg [MINADDR_W-1:0] addr_rd [N-1:0];

wire [MINDATA_W-1:0] data_rd_0 = data_rd[0];

//connect the buses
integer j,k,l;
generate
 if (W_DATA_W > R_DATA_W) 
 begin
 //write parallel
 always @(*) 
 begin
 for (j=0; j < N; j= j+1) 
 begin
 en_wr[j] = w_en;
 data_wr[j] = w_data[j*MINDATA_W +: MINDATA_W];
 addr_wr[j] = w_addr;
 end
 end

 //read serial
 always @(*) 
 begin
 for (k=0; k < N; k= k+1) 
 begin
 addr_rd[k] = r_addr[R_ADDR_W-1-:W_ADDR_W];
 end
 end

 //read address register
 reg [(R_ADDR_W-W_ADDR_W)-1:0] r_addr_lsbs_reg;
 always @(posedge clock)
 begin
 if (r_en)
 begin
 r_addr_lsbs_reg <= r_addr[(R_ADDR_W-W_ADDR_W)-1:0];
 end
 end

 //read mux
 always @(*) 
 begin
 r_data = 1'b0;
 for (l=0; l < N; l= l+1) 
 begin
 r_data = data_rd[r_addr_lsbs_reg];
 end
 end

 end 
 else if (W_DATA_W < R_DATA_W) 
 begin
 //write serial
 always @(*) 
 begin
 for (j=0; j < N; j= j+1) 
 begin
 en_wr[j] = w_en & (w_addr[(W_ADDR_W-R_ADDR_W)-1:0] == j);
 data_wr[j] = w_data;
 addr_wr[j] = w_addr[W_ADDR_W-1 -: R_ADDR_W];
 end
 end
 //read parallel
 always @(*) 
 begin
 r_data = 1'b0;
 for (k=0; k < N; k= k+1) 
 begin
 addr_rd[k] = r_addr;
 r_data[k*MINDATA_W +: MINDATA_W] = data_rd[k];
 end
 end
 end 
 else 
 begin
 //write serial
 always @(*) 
 begin
 en_wr[0] = w_en;
 data_wr[0] = w_data;
 addr_wr[0] = w_addr;
 end
 //read parallel
 always @(*) 
 begin
 addr_rd[0] = r_addr;
 r_data = data_rd_0;
 end
 end
endgenerate

genvar p;
generate
 for(p=0; p < N; p= p+1) 
 begin : ext_mem_interface_gen
 assign ext_mem_w_en[p] = en_wr[p];
 assign ext_mem_w_addr[p*MINADDR_W+:MINADDR_W] = addr_wr[p];
 assign ext_mem_w_data[p*MINDATA_W+:MINDATA_W] = data_wr[p];
 assign ext_mem_r_addr[p*MINADDR_W+:MINADDR_W] = addr_rd[p];
 assign data_rd[p] = ext_mem_r_data[p*MINDATA_W+:MINDATA_W];
 end
endgenerate
assign ext_mem_r_en = r_en;
`undef IOB_MAX
`undef IOB_MIN

localparam DATA_W = BITSIZE_dout;
localparam ADDR_W = BITSIZE_addr;

reg [BITSIZE_dout - 1 : 0] dout;

// Declare the RAM
reg [DATA_W-1:0] ram[2**ADDR_W-1:0];

integer index;
// Initialize the RAM
initial
begin
for(index=0; index<(2**ADDR_W); index=index+1)
begin
ram[index] = 0;
end
end

// Operate the RAM
always @ (posedge clock)
if(en)
if (we)
ram[addr] <= din;
else
dout <= ram[addr];

localparam DATA_W = BITSIZE_dout;

reg [BITSIZE_dout - 1 : 0] dout;

// Declare the RAM
reg [DATA_W-1:0] ram;

// Operate the RAM
always @ (posedge clock)
if(en)
if (we)
ram <= din;
else
dout <= ram;

localparam LINE2MEM_W = BITSIZE_read_addr;
localparam BE_BYTE_W = $clog2(BITSIZE_read_rdata/8);

reg [BITSIZE_read_addr - 1 : 0] read_addr;
reg replace;

reg m_axi_arvalid_int;
reg m_axi_rready_int;

assign m_axi_arvalid = m_axi_arvalid_int;
assign m_axi_rready = m_axi_rready_int;
assign m_axi_arqos = 'b0;

generate
 if(LINE2MEM_W > 0)
 begin
 //Constant AXI signals
 assign m_axi_arid = AXI_ID;
 assign m_axi_arlock = 1'b0;
 assign m_axi_arcache = 4'b0011;
 assign m_axi_arprot = 3'd0;
 //Burst parameters
 assign m_axi_arlen = 2**LINE2MEM_W -1; //will choose the burst lenght depending on the cache's and slave's data width
 assign m_axi_arsize = BE_BYTE_W; //each word will be the width of the memory for maximum bandwidth
 assign m_axi_arburst = 2'b01; //incremental burst
 assign m_axi_araddr = {BE_ADDR_W{1'b0}} + {replace_addr, {(LINE2MEM_W+BE_BYTE_W){1'b0}}}; //base address for the burst, with width extension 

 // Read Line values
 assign read_rdata = m_axi_rdata;
 assign read_valid = m_axi_rvalid;

 localparam
 idle = 2'd0,
 init_process = 2'd1,
 load_process = 2'd2,
 end_process = 2'd3;

 reg [1:0] state; 
 always @(posedge clock 1RESET_EDGE)
 begin
 if(1RESET_VALUE)
 begin
 state <= idle;
 read_addr <= 0;
 end
 else
 begin
 case (state) 
 idle:
 begin
 read_addr <= 0; 
 if(replace_valid)
 begin
 state <= init_process;
 end
 else
 begin
 state <= idle;
 end
 end

 init_process:
 begin
 read_addr <= 0; 
 if(m_axi_arready)
 begin
 state <= load_process;
 end
 else
 begin
 state <= init_process;
 end
 end

 load_process:
 begin
 if(m_axi_rvalid)
 begin
 if(m_axi_rlast)
 begin
 state <= end_process;
 read_addr <= read_addr; //to avoid writting last data in first line word
 end
 else
 begin
 read_addr <= read_addr +1;
 state <= load_process;
 end
 end
 else
 begin
 read_addr <= read_addr;
 state <= load_process;
 end
 end

 default:
 state <= idle; 
 endcase
 end
 end

 always @(*)
 begin
 m_axi_arvalid_int = 1'b0;
 m_axi_rready_int = 1'b0;
 replace = 1'b1;
 case(state)
 idle:
 begin
 replace = 1'b0;
 end

 init_process:
 begin
 m_axi_arvalid_int = 1'b1;
 end

 default:
 begin
 m_axi_rready_int = 1'b1;
 end 
 endcase
 end
 end
 else 
 begin
 //Constant AXI signals
 assign m_axi_arid = AXI_ID;
 assign m_axi_arlock = 1'b0;
 assign m_axi_arcache = 4'b0011;
 assign m_axi_arprot = 3'd0;
 //Burst parameters - single 
 assign m_axi_arlen = 8'd0; //A single burst of Memory data width word
 assign m_axi_arsize = BE_BYTE_W; //each word will be the width of the memory for maximum bandwidth
 assign m_axi_arburst = BURST_TYPE; 
 assign m_axi_araddr = {BE_ADDR_W{1'b0}} + {replace_addr, {BE_BYTE_W{1'b0}}}; //base address for the burst, with width extension 

 // Read Line values
 assign read_valid = m_axi_rvalid;
 assign read_rdata = m_axi_rdata; 

 localparam
 idle = 2'd0,
 init_process = 2'd1,
 load_process = 2'd2,
 end_process = 2'd3; 

 reg [1:0] state;

 always @(posedge clock 1RESET_EDGE)
 begin
 if(1RESET_VALUE)
 begin 
 state <= idle;
 end
 else
 begin 
 case (state) 
 idle:
 begin
 if(replace_valid)
 begin
 state <= init_process;
 end
 else
 begin
 state <= idle;
 end
 end

 init_process:
 begin 
 if(m_axi_arready)
 begin
 state <= load_process;
 end
 else
 begin
 state <= init_process;
 end
 end

 load_process:
 begin
 if(m_axi_rvalid)
 begin
 state <= end_process;
 end
 else
 begin
 state <= load_process;
 end
 end

 end_process:
 begin
 state <= idle;
 end 

 default:;
 endcase
 end
 end 

 always @(*)
 begin
 m_axi_arvalid_int = 1'b0;
 m_axi_rready_int = 1'b0;
 replace = 1'b1;
 case(state)
 idle:
 begin
 replace = 1'b0;
 end

 init_process:
 begin
 m_axi_arvalid_int = 1'b1;
 end

 load_process:
 begin
 m_axi_rready_int = 1'b1; 
 end

 default:; 
 endcase
 end 
 end 
endgenerate

localparam BE_ADDR_W = BITSIZE_mem_addr;
localparam BE_DATA_W = BITSIZE_read_rdata;
localparam BE_BYTE_W = $clog2(BE_DATA_W / 8);
localparam LINE2MEM_W = WORD_OFF_W-$clog2(BE_DATA_W/FE_DATA_W);

reg [BITSIZE_read_addr - 1 : 0] read_addr;
reg read_valid;
reg mem_valid;
reg replace;

generate
if (LINE2MEM_W > 0)
begin

reg [LINE2MEM_W-1:0] word_counter;

assign mem_addr = {BE_ADDR_W{1'b0}} + {replace_addr[FE_ADDR_W -1 - (BE_BYTE_W + LINE2MEM_W): 0], word_counter, {BE_BYTE_W{1'b0}}};


// assign read_valid = mem_ready;
assign read_rdata = mem_rdata;

localparam
idle = 2'd0,
read = 2'd1, 
delay = 2'd2;

always @ (posedge clock)
read_addr <= word_counter;

reg [1:0] state;

always @(posedge clock 1RESET_EDGE)
begin
if(1RESET_VALUE)
begin
state <= idle;
end
else
begin
case(state)

idle:
begin
if(replace_valid) //main_process flag
state <= read; 
else
state <= idle; 
end

read:
begin
state <= delay;
end

delay: 
begin
if(mem_ready)
if(read_addr == {LINE2MEM_W{1'b1}})
state <= idle;
else
begin
state <= read;
end
else
begin
state <= delay;
end
end

default:;

endcase 
end 
end


always @(*)
begin 
mem_valid = 1'b0;
replace = 1'b1;
word_counter = 0;
read_valid = 1'b0;

case(state)

idle:
begin
replace = 1'b0;
end

read:
begin
mem_valid = 1'b1;
word_counter = read_addr;
end

delay:
begin
word_counter = read_addr + mem_ready;
read_valid = mem_ready;
end
default:;


endcase
end
end // if (LINE2MEM_W > 0)
else
begin
assign mem_addr = {BE_ADDR_W{1'b0}} + {replace_addr, {BE_BYTE_W{1'b0}}};

