integer index;
localparam n_elements = 2**BITSIZE_addr;

reg [BITSIZE_w_data-1:0] memory [n_elements-1:0];

initial
begin
 for(index=0; index<n_elements; index=index+1)
 begin
 memory[index] = 0;
 end
end

assign r_data = memory[addr];

always @(posedge clock)
begin
 if (we)
 begin
 memory[addr] <= w_data;
 end
end

localparam DATA_W = BITSIZE_w_data;
reg [DATA_W-1:0] reg_file;

//read
assign r_data = reg_file;

//write
always @(posedge clock)
begin
 if(reset)
 begin
 reg_file <= {DATA_W{1'b0}};
 end
 else if (we)
 begin
 reg_file <= w_data;
 end
end

//Write Policy
`define WRITE_THROUGH 0 //write-through not allocate: implements a write-through buffer
`define WRITE_BACK 1 //write-back allocate: implementes a dirty-memory

localparam FE_NBYTES = BITSIZE_wstrb;
localparam FE_BYTE_W = $clog2(FE_NBYTES);
localparam BE_NBYTES = BE_DATA_W / 8;
localparam BE_BYTE_W = $clog2(BE_NBYTES);
localparam LINE2MEM_W = WORD_OFF_W-$clog2(BE_DATA_W/FE_DATA_W);

reg ready;
reg m_axi_awvalid_int;
reg m_axi_wvalid_int;
reg m_axi_bready_int;

assign m_axi_awvalid = m_axi_awvalid_int;
assign m_axi_wvalid = m_axi_wvalid_int;
assign m_axi_awqos = 'b0;

// Write failed signals
assign b_done = m_axi_bvalid;
reg [BITSIZE_addr - 1:0] reg_addr;
reg [FE_DATA_W + WRITE_POL*(FE_DATA_W*(2**WORD_OFF_W)-FE_DATA_W)-1 :0] reg_wdata;

localparam
 aw_idle = 2'b00,
 aw_address = 2'b01,
 aw_wait = 2'b10;

localparam
 w_idle = 1'b0,
 w_active = 1'b1;

reg [1:0] aw_state;
reg [0:0] w_state; 

genvar i;
generate
 if(WRITE_POL == `WRITE_THROUGH) 
 begin
 //Constant AXI signals
 assign m_axi_awid = AXI_ID;
 assign m_axi_awlen = 8'd0;
 assign m_axi_awsize = BE_BYTE_W; // verify - Writes data of the size of BE_DATA_W
 assign m_axi_awburst = BURST_TYPE;
 assign m_axi_awlock = 1'b0; // 00 - Normal Access
 assign m_axi_awcache = 4'b0011;
 assign m_axi_awprot = 3'd0;
 assign m_axi_wlast = m_axi_wvalid_int;
 assign m_axi_bready = 1'b1;
 //AXI Buffer Output signals
 assign m_axi_awaddr = {BE_ADDR_W{1'b0}} + {addr[BITSIZE_addr-1 : (BE_BYTE_W - FE_BYTE_W)], {BE_BYTE_W{1'b0}}};

 if(BE_DATA_W == FE_DATA_W)
 begin
 assign m_axi_wstrb = wstrb;
 assign m_axi_wdata = reg_wdata;
 end
 else
 begin
 wire [BE_BYTE_W - FE_BYTE_W -1 :0] word_align = reg_addr[0 +: (BE_BYTE_W - FE_BYTE_W)];
 assign m_axi_wstrb = wstrb << (word_align * FE_NBYTES);
 for (i = 0; i < BE_DATA_W/FE_DATA_W; i = i +1) 
 begin : wdata_block
 assign m_axi_wdata[(i+1)*FE_DATA_W-1:i*FE_DATA_W] = reg_wdata;
 end
 end

 always @(posedge clock 1RESET_EDGE) 
 begin
 if(1RESET_VALUE) 
 begin
 aw_state <= aw_idle;
 w_state <= w_idle;
 end 
 else 
 begin
 case(aw_state) 
 aw_idle: 
 begin
 if(valid) 
 begin
 aw_state <= aw_address;
 end 
 else
 begin
 aw_state <= aw_idle;
 end
 end
 aw_address: 
 begin
 if(m_axi_awready && w_state == w_idle) 
 begin
 aw_state <= aw_idle; /* Address written, can write data */
 w_state <= w_active;
 reg_addr <= addr;
 reg_wdata <= wdata;
 end 
 else 
 begin
 if (m_axi_awready) 
 begin 
 aw_state <= aw_wait; /* Address written, but data channel busy */
 end
 else
 begin
 aw_state <= aw_address; /* Address not written yet */
 end
 end
 end
 aw_wait : 
 begin
 if(w_state == w_idle) 
 begin
 aw_state <= aw_idle;
 w_state <= w_active;
 reg_addr <= addr;
 reg_wdata <= wdata;
 end 
 else
 begin
 aw_state <= aw_wait;
 end
 end
 default : 
 begin
 aw_state <= aw_idle;
 w_state <= w_idle;
 end
 endcase

 if(w_state == w_active && m_axi_wready)
 begin
 w_state <= w_idle;
 end
 end 
 end
 end 
 else 
 begin
 if(LINE2MEM_W > 0) 
 begin
 //Constant AXI signals
 assign m_axi_awid = AXI_ID;
 assign m_axi_awlock = 1'b0;
 assign m_axi_awcache = 4'b0011;
 assign m_axi_awprot = 3'd0;

 //Burst parameters
 assign m_axi_awlen = 2**LINE2MEM_W -1; //will choose the burst lenght depending on the cache's and slave's data width
 assign m_axi_awsize = BE_BYTE_W; //each word will be the width of the memory for maximum bandwidth
 assign m_axi_awburst = 2'b01; //incremental burst
 assign m_axi_bready = 1'b1;

 //memory address
 assign m_axi_awaddr = {BE_ADDR_W{1'b0}} + {addr, {(FE_BYTE_W+WORD_OFF_W){1'b0}}}; //base address for the burst, with width extension

 // memory write-data
 reg [LINE2MEM_W-1:0] word_counter = 'b0;
 assign m_axi_wdata = reg_wdata >> (word_counter*BE_DATA_W);
 assign m_axi_wstrb = {BE_NBYTES{1'b1}};
 assign m_axi_wlast = &word_counter & m_axi_wvalid; 

 always @(posedge clock 1RESET_EDGE) 
 begin
 if(1RESET_VALUE) 
 begin
 aw_state <= aw_idle;
 w_state <= w_idle;
 end 
 else 
 begin
 case(aw_state) 
 aw_idle: 
 begin
 if(valid) 
 begin
 aw_state <= aw_address;
 end 
 else
 begin
 aw_state <= aw_idle;
 end
 end
 aw_address: 
 begin
 if(m_axi_awready && w_state == w_idle) 
 begin
 aw_state <= aw_idle; /* Address written, can write data */
 w_state <= w_active;
 reg_wdata <= wdata;
 end 
 else 
 if (m_axi_awready) 
 begin 
 aw_state <= aw_wait; /* Address written, but data channel busy */
 end
 else
 begin
 aw_state <= aw_address; /* Address not written yet */
 end
 end
 aw_wait: 
 begin
 if(w_state == w_idle) 
 begin
 aw_state <= aw_idle;
 w_state <= w_active;
 reg_wdata <= wdata;
 end 
 else
 begin
 aw_state <= aw_wait;
 end
 end
 default : 
 begin
 aw_state <= aw_idle;
 w_state <= w_idle;
 end
 endcase

 if(w_state == w_active) 
 begin
 if(m_axi_wready && (&word_counter)) 
 begin
 w_state <= w_idle;
 word_counter <= 'b0;
 end 
 else if(m_axi_wready) 
 begin
 word_counter <= word_counter + 1;
 w_state <= w_active;
 end
 end
 end 
 end
 end
 else 
 begin 
 //Constant AXI signals
 assign m_axi_awid = AXI_ID;
 assign m_axi_awlock = 1'b0;
 assign m_axi_awcache = 4'b0011;
 assign m_axi_awprot = 3'd0;

 //Burst parameters - single
 assign m_axi_awlen = 8'd0; //A single burst of Memory data width word
 assign m_axi_awsize = BE_BYTE_W; //each word will be the width of the memory for maximum bandwidth
 assign m_axi_awburst = BURST_TYPE;
 assign m_axi_bready = 1'b1;

 //memory address
 assign m_axi_awaddr = {BE_ADDR_W{1'b0}} + {addr, {BE_BYTE_W{1'b0}}}; //base address for the burst, with width extension

 //memory write-data
 assign m_axi_wdata = reg_wdata;
 assign m_axi_wstrb = {BE_NBYTES{1'b1}}; //uses entire bandwidth
 assign m_axi_wlast = m_axi_wvalid;

 always @(posedge clock 1RESET_EDGE) 
 begin
 if(1RESET_VALUE) 
 begin
 aw_state <= aw_idle;
 w_state <= w_idle;
 end 
 else 
 begin
 case(aw_state) 
 aw_idle: 
 begin
 if(valid) 
 begin
 aw_state <= aw_address;
 end 
 else
 begin
 aw_state <= aw_idle;
 end
 end
 aw_address: begin
 if(m_axi_awready && w_state == w_idle) 
 begin
 aw_state <= aw_idle; /* Address written, can write data */
 w_state <= w_active;
 reg_wdata <= wdata;
 end 
 else if (m_axi_awready) 
 begin 
 aw_state <= aw_wait; /* Address written, but data channel busy */
 end
 else
 begin
 aw_state <= aw_address; /* Address not written yet */
 end
 end
 aw_wait : 
 begin
 if(w_state == w_idle) 
 begin
 aw_state <= aw_idle;
 w_state <= w_active;
 reg_wdata <= wdata;
 end 
 else
 begin
 aw_state <= aw_wait;
 end
 end
 default : 
 begin
 aw_state <= aw_idle;
 w_state <= w_idle;
 end
 endcase

 if(w_state == w_active) 
 begin
 if(m_axi_wready) 
 begin
 w_state <= w_idle;
 end
 end
 end 
 end 
 end
 end
endgenerate

always @(*) 
begin
 m_axi_awvalid_int = 1'b0;
 m_axi_wvalid_int = 1'b0;
 ready = 1'b0;
 case(aw_state)
 aw_idle:
 begin
 ready = 1'b1;
 end
 aw_address:
 begin
 m_axi_awvalid_int = 1'b1;
 end
 endcase
 if(w_state == w_active) 
 begin
 m_axi_wvalid_int = 1'b1;
 end
end 
`undef WRITE_THROUGH
`undef WRITE_BACK

localparam FE_NBYTES = BITSIZE_wstrb;
localparam FE_BYTE_W = $clog2(FE_NBYTES);
localparam BE_ADDR_W = BITSIZE_mem_addr;
localparam BE_DATA_W = BITSIZE_mem_wdata;
localparam BE_NBYTES = BE_DATA_W / 8;
localparam BE_BYTE_W = $clog2(BE_NBYTES);
localparam LINE2MEM_W = WORD_OFF_W-$clog2(BE_DATA_W/FE_DATA_W);

reg mem_wstrb;
reg ready;
reg mem_valid;



assign write_done=mem_ready;

genvar i;

generate
if(WRITE_POL == 0) begin

assign mem_addr = {BE_ADDR_W{1'b0}} + {addr[FE_ADDR_W-1 - (FE_BYTE_W + WRITE_POL*WORD_OFF_W) :BE_BYTE_W - (FE_BYTE_W + WRITE_POL*WORD_OFF_W)], {BE_BYTE_W{1'b0}}};

localparam
idle = 2'd0,
write = 2'd1,
delay = 2'd2;

reg [1:0] state;
if(BE_DATA_W == FE_DATA_W) begin
assign mem_wdata = wdata;
always @(*) begin
mem_wstrb = 0;
case(state)
write: mem_wstrb = wstrb;
default:;
endcase // case (state)
end // always @ *
end
else begin
wire [BE_BYTE_W-FE_BYTE_W -1 :0] word_align = addr[FE_BYTE_W - (FE_BYTE_W + WRITE_POL*WORD_OFF_W) +: (BE_BYTE_W - FE_BYTE_W)];

for (i = 0; i < BE_DATA_W/FE_DATA_W; i = i +1) begin : wdata_block
assign mem_wdata[(i+1)*FE_DATA_W-1:i*FE_DATA_W] = wdata;
end

always @(*) begin
mem_wstrb = 0;
case(state)
write: mem_wstrb = wstrb << word_align * FE_NBYTES;
default:;
endcase // case (state)
end // always @ *
end

always @(posedge clock 1RESET_EDGE) begin
if(1RESET_VALUE)
state <= idle;
else
case(state)
idle: begin
if(valid)
state <= write;
else
state <= idle;
end
write: begin
state <= delay;
end
default: begin /* delay */
if(mem_ready & ~valid)
state <= idle;
else
if(mem_ready & valid) //still has data to write
state <= write;
else
state <= delay;
end
endcase // case (state)
end // always @ (posedge clock 1RESET_EDGE)

always @(*)
begin
ready = 1'b0;
mem_valid = 1'b0;
case(state)
idle:
ready = 1'b1;
write:
mem_valid = ~mem_ready;
default: /* delay */
begin
ready = mem_ready;
end
endcase // case (state)
end
end // if (WRITE_POL == WRITE_THROUGH)
//////////////////////////////////////////////////////////////////////////////////////////////
else begin // if (WRITE_POL == WRITE_BACK)

if (LINE2MEM_W > 0) begin

reg [LINE2MEM_W-1:0] word_counter, word_counter_reg;
always @(posedge clock) word_counter_reg <= word_counter;

// memory address
assign mem_addr = {BE_ADDR_W{1'b0}} + {addr[FE_ADDR_W-1 - (FE_BYTE_W + WRITE_POL*WORD_OFF_W) : BE_BYTE_W + LINE2MEM_W - (FE_BYTE_W + WRITE_POL*WORD_OFF_W)], word_counter, {BE_BYTE_W{1'b0}}};
// memory write-data
assign mem_wdata = wdata>>(BE_DATA_W*word_counter);

localparam
idle = 2'd0,
write = 2'd1,
delay = 2'd2;

reg [1:0] state;

always @(posedge clock 1RESET_EDGE)
begin
if(1RESET_VALUE)
state <= idle;
else
case(state)

idle:
begin
if(valid)
state <= write;
else
state <= idle;
end

write:
state <= delay;
default: /* delay */
begin
if(mem_ready & (&word_counter_reg))
state <= idle;
else if(mem_ready)
state <= write;
else
state <= delay;
end
endcase // case (state)
end // always @ (posedge clock 1RESET_EDGE)

always @(*)
begin
ready = 1'b0;
mem_valid = 1'b0;
mem_wstrb = 0;
word_counter = 0;

case(state)
idle:
begin
ready = ~valid;
if(valid) mem_wstrb = {BE_NBYTES{1'b1}};
else mem_wstrb =0;
end

write:
begin
mem_valid = ~(mem_ready & (&word_counter));
mem_wstrb = {BE_NBYTES{1'b1}};
word_counter = word_counter_reg;
end
default: /* delay */
begin
ready = mem_ready & (&word_counter); //last word transfered
word_counter = word_counter_reg + mem_ready;
end
endcase // case (state)
end

end // if (LINE2MEM_W > 0)
else begin // if (LINE2MEM_W == 0)

// memory address
assign mem_addr = {BE_ADDR_W{1'b0}} + {addr[FE_ADDR_W-1 - (FE_BYTE_W + WRITE_POL*WORD_OFF_W) : BE_BYTE_W - (FE_BYTE_W + WRITE_POL*WORD_OFF_W)], {BE_BYTE_W{1'b0}}};
// memory write-data
assign mem_wdata = wdata;

localparam
idle = 2'd0,
write = 2'd1,
delay = 2'd2;

reg [1:0] state;

always @(posedge clock 1RESET_EDGE)
begin
if(1RESET_VALUE)
state <= idle;
else
case(state)

idle:
begin
if(valid)
state <= write;
else
state <= idle;
end

write:
begin
state <= delay;
end
default:
begin
if(mem_ready)
state <= idle;
else
state <= delay;
end
endcase // case (state)
end // always @ (posedge clock 1RESET_EDGE)

always @(*)
begin
ready = 1'b0;
mem_valid = 1'b0;
mem_wstrb = 0;

case(state)
idle:
begin
ready = ~valid;
if(valid) mem_wstrb = {BE_NBYTES{1'b1}};
else mem_wstrb = 0;
end

write:
begin
mem_valid = ~mem_ready;
mem_wstrb = {BE_NBYTES{1'b1}};
end
default: /* delay */
begin
ready = mem_ready;
end
endcase // case (state)
end // always @ *

end // else: !if(LINE2MEM_W > 0)
end // else: !if(WRITE_POL == WRITE_THROUGH)
endgenerate

generate
