assign Mout_oe_ram = int_sel_LOAD ? 1'b1 : Min_oe_ram;
assign Mout_we_ram = int_sel_STORE ? 1'b1 : Min_we_ram;
assign out1 = M_Rdata_ram[BITSIZE_out1-1:0];
assign Mout_Wdata_ram = int_sel_STORE ? in1 : Min_Wdata_ram;
assign Mout_data_ram_size = int_sel_STORE || int_sel_LOAD ? in3[BITSIZE_in3-1:0] : Min_data_ram_size;
assign done_port = (M_DataRdy && in4) || (!in4 && (sel_STORE || sel_LOAD));
// Add assertion here
// psl default clock = (posedge clock);
// psl ERROR_Min_we_ram_Min_oe_ram: assert never {Min_we_ram && Min_oe_ram};
// psl ERROR_LOAD_Min_oe_ram: assert never {int_sel_LOAD && Min_oe_ram};
// psl ERROR_STORE_Min_we_ram: assert never {int_sel_STORE && Min_we_ram};
// psl ERROR_STORE_LOAD: assert never {int_sel_STORE && int_sel_LOAD};

localparam max_n_writes = PORTSIZE_sel_STORE > PORTSIZE_Mout_we_ram ? PORTSIZE_sel_STORE : PORTSIZE_Mout_we_ram;
localparam max_n_reads = PORTSIZE_sel_LOAD > PORTSIZE_Mout_oe_ram ? PORTSIZE_sel_STORE : PORTSIZE_Mout_oe_ram;
localparam max_n_rw = max_n_writes > max_n_reads ? max_n_writes : max_n_reads;
wire [PORTSIZE_sel_LOAD-1:0] int_sel_LOAD;
wire [PORTSIZE_sel_STORE-1:0] int_sel_STORE;

generate 
 if(USE_BACK_PRESSURE == 1)
 begin
 reg [PORTSIZE_sel_LOAD-1:0] int_sel_LOAD_old;
 reg [PORTSIZE_sel_STORE-1:0] int_sel_STORE_old;
 wire [PORTSIZE_sel_LOAD-1:0] int_sel_LOAD_old_next;
 wire [PORTSIZE_sel_STORE-1:0] int_sel_STORE_old_next;

