reg oe_ack 1INIT_ZERO_VALUE;
reg internal_previous;
wire oe_ack_next;

assign out1 = in1;
assign internal = ALLOCATED_ADDRESS == S_addr_ram;
assign Sout_DataRdy = oe_ack || Sin_DataRdy;
assign Sout_Rdata_ram = internal_previous ? register : Sin_Rdata_ram; 


assign oe_ack_next = internal & ~oe_ack;
always @(posedge clock 1RESET_EDGE) begin
 if (1RESET_VALUE) begin
 register <= {BITSIZE_in1{1'b0}};
 oe_ack <= 1'b0;
 internal_previous <= 1'b0;
 end
 else begin
 if (done_port)
 register <= in1;
 oe_ack <= oe_ack_next;
 internal_previous <= internal;
 end
end

NP_functionality.VHDL_PROVIDED:
begin
 process(in1, in2)
 begin
 out1 <= resize_signed(shift_right(in1, to_integer(unsigned(in2) rem PRECISION)), BITSIZE_out1);
 end process;

NP_functionality.VERILOG_PROVIDED:
`ifndef _SIM_HAVE_CLOG2
 function integer log2;
 input integer value;
 integer temp_value;
 begin
 temp_value = value-1;
 for (log2=0; temp_value>0; log2=log2+1)
 temp_value = temp_value>>1;
 end
 endfunction
`endif
`ifdef _SIM_HAVE_CLOG2
 localparam arg2_bitsize = $clog2(PRECISION);
`else
 localparam arg2_bitsize = log2(PRECISION);
`endif
generate
 if(BITSIZE_in2 > arg2_bitsize)
 assign out1 = in1 >>> (in2[arg2_bitsize-1:0]);
 else
 assign out1 = in1 >>> in2;
endgenerate

wire signed [BITSIZE_out1-1:0] sub_tmp;
wire signed [BITSIZE_out1-1:0] mask_max;
wire signed [BITSIZE_out1-1:0] mask_min;
wire cond1, cond2;
assign sub_tmp = in1 - in2;
assign mask_min = {1'b1, {BITSIZE_out1-1{1'b0}}};
assign mask_max = {1'b0, {BITSIZE_out1-1{1'b1}}};
assign cond1 = (!in1[BITSIZE_in1-1])&in2[BITSIZE_in2-1]&sub_tmp[BITSIZE_out1-1];
assign cond2 = in1[BITSIZE_in1-1]&(!in2[BITSIZE_in2-1])&(!sub_tmp[BITSIZE_out1-1]);
assign out1 = cond2 ? mask_min : (cond1 ? mask_max : sub_tmp);

wire signed [BITSIZE_out1-1:0] add_tmp;
wire signed [BITSIZE_out1-1:0] mask_max;
wire signed [BITSIZE_out1-1:0] mask_min;
wire cond1, cond2;
assign add_tmp = in1 + in2;
assign mask_min = {1'b1, {BITSIZE_out1-1{1'b0}}};
assign mask_max = {1'b0, {BITSIZE_out1-1{1'b1}}};
assign cond1 = (!in1[BITSIZE_in1-1])&(!in2[BITSIZE_in2-1])&add_tmp[BITSIZE_out1-1];
assign cond2 = in1[BITSIZE_in1-1]&in2[BITSIZE_in2-1]&(!add_tmp[BITSIZE_out1-1]);
assign out1 = cond2 ? mask_min : (cond1 ? mask_max : add_tmp);

wire [BITSIZE_S_addr_ram - 1:0] statusRegister;
reg [BITSIZE_S_addr_ram - 1:0] ackAddress 1INIT_ZERO_VALUE;
