function [PORTSIZE_S_addr_ram-1:0] check_condition;
 input [PORTSIZE_S_addr_ram*BITSIZE_S_addr_ram-1:0] m;
 integer i1;
begin
 for(i1 = 0; i1 < PORTSIZE_S_addr_ram; i1 = i1 + 1)
 begin
 check_condition[i1] = m[i1*BITSIZE_S_addr_ram +:BITSIZE_S_addr_ram] == ALLOCATED_ADDRESS;
 end
end
endfunction
function [BITSIZE_S_addr_ram-1:0] extract_value;
 input [PORTSIZE_S_addr_ram-1:0] cond;
 input [PORTSIZE_S_Wdata_ram*BITSIZE_S_Wdata_ram-1:0] value;
 reg [BITSIZE_S_addr_ram-1:0] res;
 integer i1;
begin
 res={BITSIZE_S_addr_ram{1'b0}};
 for(i1 = 0; i1 < PORTSIZE_S_Wdata_ram; i1 = i1 + 1)
 begin
 res = res | ( cond[i1] ? value[i1*BITSIZE_S_Wdata_ram +:BITSIZE_S_Wdata_ram] : {BITSIZE_S_addr_ram{1'b0}});
 end
 extract_value = res;
end
endfunction
function [PORTSIZE_Sout_Rdata_ram*BITSIZE_Sout_Rdata_ram-1:0] inject_value;
 input [PORTSIZE_S_addr_ram-1:0] cond;
 input [BITSIZE_S_addr_ram-1:0] value;
 input [PORTSIZE_Sin_Rdata_ram*BITSIZE_Sin_Rdata_ram-1:0] m;
 integer i1;
begin
 for(i1 = 0; i1 < PORTSIZE_Sout_Rdata_ram; i1 = i1 + 1)
 begin
 inject_value[i1*BITSIZE_Sout_Rdata_ram +:BITSIZE_Sout_Rdata_ram] = cond[i1] ? value : m[i1*BITSIZE_Sin_Rdata_ram +:BITSIZE_Sin_Rdata_ram];
 end
end
endfunction

assign control = statusRegister[0];
assign internal = check_condition(S_addr_ram);
assign statusRegister = {ackAddress[BITSIZE_S_addr_ram - 1:2], state};
assign notifyAddress = {ackAddress[BITSIZE_S_addr_ram-1:2], 2'd0};
assign Sout_DataRdy = internal | Sin_DataRdy; 
assign Sout_Rdata_ram = inject_value(internal & S_oe_ram, statusRegister, Sin_Rdata_ram);

always @ (*)
begin
 ackAddress_next = ackAddress;
 if (|(internal & S_we_ram))
 ackAddress_next = extract_value(internal & S_we_ram,S_Wdata_ram);
end // always @ (*)

always @ (posedge clock 1RESET_EDGE) begin
 if (1RESET_VALUE) begin
 state <= 2'd0;
 ackAddress <= {BITSIZE_S_addr_ram{1'b0}};
 start_port <= 1'b0;
 end else begin
 state <= state_next;
 ackAddress <= ackAddress_next;
 start_port <= next_start_port;
 end
end 

always @ (*) begin
 state_next = state;
 next_start_port = 1'b0;

 if (state == 2'd0) begin
 if (internal & S_we_ram) begin
 state_next = 2'd1;
 next_start_port = 1'b1;
 end
 end else if (state == 2'd1) begin
 if (done_port) begin
 state_next = 2'd2;
 end
 end else if (state == 2'd2) begin
 if (notified) begin
 state_next = 2'd0;
 end
 end else begin
 end
end

