 rounding(0) <= mantissa1(28) when (unsigned(mantissa1(28 downto 0)) /= 0) else mantissa1(28) or mantissa1(29);
 exp_temp <= (not exponent1(7)) & exponent1(6 downto 0);
 expmantissa <= std_logic_vector(unsigned('0' & exp_temp & mantissa1(51 downto 29)) + unsigned(rounding));
 is_Nan <= is_all_ones and not is_mantissa_zero;
 is_zero <= is_exp_zero or underflow;
 is_infinite <= (is_all_ones and is_mantissa_zero) or (not is_NaN and (overflow or expmantissa(31)));
 out1(31) <= in1(63);
 out1(30 downto 23) <= "00000000" when(is_zero = '1') else "11111111" when ((is_all_ones or overflow or expmantissa(31)) = '1') else expmantissa(30 downto 23);
 out1(22 downto 0) <= (others => '0') when ((is_zero or is_infinite) = '1') else (22 => '1', others => '0') when (is_NaN = '1') else expmantissa(22 downto 0);

NP_functionality.VERILOG_PROVIDED:
wire [10:0] exponent1;
wire [51:0] mantissa1;
wire is_exp_zero;
wire is_all_ones;
wire is_mantissa_zero;
wire underflow;
wire overflow;
wire rounding;
wire [7:0] exp_temp;
wire [31:0] expmantissa;
wire is_NaN;
wire is_zero;
wire is_infinite;

assign exponent1 = in1[62:52];
assign mantissa1 = in1[51:0];
assign is_exp_zero = exponent1 == 11'd0;
assign is_all_ones = exponent1 == {11{1'b1}};
assign is_mantissa_zero = mantissa1 == 52'd0;

assign underflow = exponent1 <= 11'd896;
assign overflow = 11'd1151 <= exponent1;
assign rounding = mantissa1[28] && ((mantissa1[27:0] != 28'd0) | mantissa1[29]);

assign exp_temp = {!exponent1[7], exponent1[6:0]};
assign expmantissa = {1'b0, exp_temp, mantissa1[51:29]} + {31'd0, rounding};

 assign is_NaN = is_all_ones & !is_mantissa_zero;
 assign is_zero = is_exp_zero | underflow;
 assign is_infinite = (is_all_ones & is_mantissa_zero) | (!is_NaN & (overflow | expmantissa[31]));
 assign out1[31] = in1[63];
 assign out1[30:23] = is_zero ? 8'd0 : (is_all_ones|overflow|expmantissa[31] ? {8{1'b1}} : expmantissa[30:23]);
 assign out1[22:0] = is_zero|is_infinite ? 23'd0 : (is_NaN ? {1'b1,22'd0} : expmantissa[22:0]);

`ifndef _SIM_HAVE_CLOG2
 function integer log2;
 input integer value;
 integer temp_value;
 begin
 temp_value = value-1;
 for (log2=0; temp_value>0; log2=log2+1)
 temp_value = temp_value>>1;
 end
 endfunction
`endif
`ifdef _SIM_HAVE_CLOG2
 localparam nbit_addr = MAX_ADDRESS == 1 ? 1 : $clog2(MAX_ADDRESS);
`else
 localparam nbit_addr = MAX_ADDRESS == 1 ? 1 : log2(MAX_ADDRESS);
`endif

generate
if (BITSIZE_out1 <= nbit_addr)
begin
 assign out1 = in1[BITSIZE_out1-1:0];
end
else
begin
 assign out1 = {{(BITSIZE_out1-nbit_addr-1){1'b0}},in1[nbit_addr:0]};
end
endgenerate

reg isInRange;
always @ (address or base or max_address)
 if (address >= base && address <= max_address)
 isInRange = 1'b1;
 else
 isInRange = 1'b0;

reg [BITSIZE_sel - 1:0] sel;

generate
 if (BITSIZE_dataRamSize == 4)
 begin
 always @ (dataRamSize)
 case (dataRamSize)
 4'd8: sel = {{BITSIZE_sel-1{1'b0}}, 1'h1};
 default: sel = {BITSIZE_sel{1'b1}};
 endcase
 end
 if (BITSIZE_dataRamSize == 5)
 begin
 always @ (dataRamSize)
 case (dataRamSize)
 5'd8: sel = {{BITSIZE_sel-1{1'b0}}, 1'h1};
 5'd16: sel = {{BITSIZE_sel-2{1'b0}}, 2'h3};
 default: sel = {BITSIZE_sel{1'b1}};
 endcase
 end
 if (BITSIZE_dataRamSize == 6)
 begin
 always @ (dataRamSize)
 case (dataRamSize)
 6'd8: sel = {{BITSIZE_sel-1{1'b0}}, 1'h1};
 6'd16: sel = {{BITSIZE_sel-2{1'b0}}, 2'h3};
 6'd32: sel = {{BITSIZE_sel-4{1'b0}}, 4'hf};
 default: sel = {BITSIZE_sel{1'b1}};
 endcase
 end
 if (BITSIZE_dataRamSize == 7)
 begin
 always @ (dataRamSize)
 case (dataRamSize)
 7'd8: sel = {{BITSIZE_sel-1{1'b0}}, 1'h1};
 7'd16: sel = {{BITSIZE_sel-2{1'b0}}, 2'h3};
 7'd32: sel = {{BITSIZE_sel-4{1'b0}}, 4'hf};
 7'd64: sel = {{BITSIZE_sel-8{1'b0}}, 8'hff};
 default: sel = {BITSIZE_sel{1'b1}};
 endcase
 end
 if (BITSIZE_dataRamSize == 8)
 begin
 always @ (dataRamSize)
 case (dataRamSize)
 8'd8: sel = {{BITSIZE_sel-1{1'b0}}, 1'h1};
 8'd16: sel = {{BITSIZE_sel-2{1'b0}}, 2'h3};
 8'd32: sel = {{BITSIZE_sel-4{1'b0}}, 4'hf};
 8'd64: sel = {{BITSIZE_sel-8{1'b0}}, 8'hff};
 8'd128: sel = {{BITSIZE_sel-16{1'b0}}, 16'hffff};
 default: sel = {BITSIZE_sel{1'b1}};
 endcase
 end
endgenerate

reg [PORTSIZE_arb_grant-1:0] arb_grant 1INIT_ZERO_VALUE;
reg [PORTSIZE_arb_grant-1:0] arb_grant_next;

always @ (arb_requests, arb_grant)
begin : ARBITER
integer i, busy, stop;

busy = 0;
stop = 0;

for (i = 0; i < PORTSIZE_arb_requests; i = i + 1)
if (arb_requests[i] == arb_grant[i] && arb_grant[i] == 1'b1)
busy = 1;

if (busy == 1)
// I don't want to interrupt ongoing cycles.
arb_grant_next = arb_grant;
else
for (i = 0; i < PORTSIZE_arb_requests; i = i + 1)
if (stop == 0 && arb_requests[i] == 1'b1) begin
arb_grant_next[i] = 1'b1;
stop = 1;
end else
arb_grant_next[i] = 1'b0;
end

always @ (posedge clock 1RESET_EDGE)
if (1RESET_VALUE) begin
arb_grant = {PORTSIZE_arb_grant{1'b0}};
end
else begin
arb_grant = arb_grant_next;
end

reg oe_int_delayed 1INIT_ZERO_VALUE;
assign out1 = !((we1 & internal1) | oe_int_delayed);
always @(posedge clock)
 oe_int_delayed <= oe1 & internal1;

reg [BITSIZE_addr_om-1:0] addr_om;
reg cyc_om;
reg stb_om;
reg we_om;
reg outctrl;
reg state 1INIT_ZERO_VALUE;
reg state_next;
wire [BITSIZE_status_reg-1:0] notify_addr;

assign notify_addr = {status_reg[BITSIZE_status_reg-1:2], {2{1'b0}}};

always @ (posedge clock 1RESET_EDGE)
 if (1RESET_VALUE)
 begin
 state <= 1'b0;
 end
 else
 begin
 state <= state_next;
 end

always @ (*)
 begin
 state_next = 1'b0;
 cyc_om = 1'b0;
 stb_om = 1'b0;
 addr_om = {BITSIZE_addr_om{1'b0}};
 we_om = 1'b0;
 outctrl = 1'b0;
 if (state == 1'b0)
 begin
 if (done_port == 1'b1 && (| notify_addr))
 begin
 state_next = 1'b1;
 cyc_om = 1'b1;
 stb_om = 1'b1;
 addr_om = notify_addr;
 we_om = 1'b1;
 outctrl = 1'b1;
 end
 else
 state_next = 1'b0;
 end
 else
 begin
 cyc_om = 1'b1;
 stb_om = 1'b1;
 addr_om = notify_addr;
 we_om = 1'b1;
 outctrl = 1'b1;
 if (ack_im == 1'b1)
 state_next = 1'b0;
 else
 state_next = 1'b1;
 end
 end

wire ack_temp;
reg [BITSIZE_out1-1:0] reg_out1 1INIT_ZERO_VALUE;
assign out1 = reg_out1;
assign ack_temp = ALLOCATED_ADDRESS == address;
assign ack = ack_temp;
always @(posedge clock 1RESET_EDGE)
 if (1RESET_VALUE)
 reg_out1 <= {BITSIZE_out1{1'b0}};
 else if (wenable && ack_temp)
 reg_out1 <= in1;

reg [BITSIZE_dataRamSize - 1:0] dataRamSize;

generate
 if (BITSIZE_sel == 1)
 begin
 always @ (sel)
 dataRamSize = { {BITSIZE_dataRamSize-4{1'b0}}, 4'd8};
 end // if (BITSIZE_sel == 4)
 if (BITSIZE_sel == 2)
 begin
 always @ (sel)
 case (sel)
 2'h1: dataRamSize = { {BITSIZE_dataRamSize-4{1'b0}}, 4'd8};
 default: dataRamSize = { 1'b1, {BITSIZE_dataRamSize-1{1'b0}}};
 endcase // case (sel)
 end
 if (BITSIZE_sel == 4)
 begin
 if (BITSIZE_dataRamSize > 4)
 begin
 always @ (sel)
 case (sel)
 4'h1: dataRamSize = { {BITSIZE_dataRamSize-4{1'b0}}, 4'd8};
 4'h3: dataRamSize = { {BITSIZE_dataRamSize-5{1'b0}}, 5'd16};
 default: dataRamSize = { 1'b1, {BITSIZE_dataRamSize-1{1'b0}}};
 endcase // case (sel)
 end
 else
 begin
 always @ (sel)
 dataRamSize = { 1'b1, {BITSIZE_dataRamSize-1{1'b0}}};
 end
 end
 if (BITSIZE_sel == 8)
 begin
 if (BITSIZE_dataRamSize > 5)
 begin
 always @ (sel)
 case (sel)
 8'h1: dataRamSize = { {BITSIZE_dataRamSize-4{1'b0}}, 4'd8};
 8'h3: dataRamSize = { {BITSIZE_dataRamSize-5{1'b0}}, 5'd16};
 8'hf: dataRamSize = { {BITSIZE_dataRamSize-6{1'b0}}, 6'd32};
 default: dataRamSize = { 1'b1, {BITSIZE_dataRamSize-1{1'b0}}};
 endcase // case (sel)
 end
 else if (BITSIZE_dataRamSize == 5)
 begin
 always @ (sel)
 case (sel)
 8'h1: dataRamSize = { {BITSIZE_dataRamSize-4{1'b0}}, 4'd8};
 8'h3: dataRamSize = { {BITSIZE_dataRamSize-5{1'b0}}, 5'd16};
 default: dataRamSize = { 1'b1, {BITSIZE_dataRamSize-1{1'b0}}};
 endcase // case (sel)
 end
 else
 begin
 always @ (sel)
 dataRamSize = { 1'b1, {BITSIZE_dataRamSize-1{1'b0}}};
 end
 end
 if (BITSIZE_sel == 16)
 begin
 if (BITSIZE_dataRamSize > 6)
 begin
 always @ (sel)
 case (sel)
 16'h1: dataRamSize = { {BITSIZE_dataRamSize-4{1'b0}}, 4'd8};
 16'h3: dataRamSize = { {BITSIZE_dataRamSize-5{1'b0}}, 5'd16};
 16'hf: dataRamSize = { {BITSIZE_dataRamSize-6{1'b0}}, 6'd32};
 16'hff: dataRamSize = { {BITSIZE_dataRamSize-7{1'b0}}, 7'd64};
 default: dataRamSize = { 1'b1, {BITSIZE_dataRamSize-1{1'b0}}};
 endcase // case (sel)
 end
 else if (BITSIZE_dataRamSize == 6)
 begin
 always @ (sel)
 case (sel)
 16'h1: dataRamSize = { {BITSIZE_dataRamSize-4{1'b0}}, 4'd8};
 16'h3: dataRamSize = { {BITSIZE_dataRamSize-5{1'b0}}, 5'd16};
 16'hf: dataRamSize = { {BITSIZE_dataRamSize-6{1'b0}}, 6'd32};
 default: dataRamSize = { 1'b1, {BITSIZE_dataRamSize-1{1'b0}}};
 endcase // case (sel)
 end
 else if (BITSIZE_dataRamSize == 5)
 begin
 always @ (sel)
 case (sel)
 16'h1: dataRamSize = { {BITSIZE_dataRamSize-4{1'b0}}, 4'd8};
 16'h3: dataRamSize = { {BITSIZE_dataRamSize-5{1'b0}}, 5'd16};
 default: dataRamSize = { 1'b1, {BITSIZE_dataRamSize-1{1'b0}}};
 endcase // case (sel)
 end
 else
 begin
 always @ (sel)
 dataRamSize = { 1'b1, {BITSIZE_dataRamSize-1{1'b0}}};
 end
